export function useMemorySheetUI({
    getActiveChatChar,
    currentMessages,
    selectedMessages,
    clearSelection,
    memoryBooksSheet,
    loadCurrentMemoryBook,
    generateMemoryDraftForMessages,
    generateSingleDraft,
