        content.querySelector('#memory-prompt-preview-close')?.addEventListener('click', () => {
            closeBottomSheet();
            if (hasOnClose) {
                setTimeout(() => onClose(), 50);
            }
        });
        showBottomSheet({ title: 'Generation Rule', content, isSolid: true });
