export async function executeImpersonationUseCase({
    char,
    guidanceText,
    controller,
    services
}) {
    const {
        notifyGenerationStarted,
        notifyGenerationEnded
    } = services.app;

    const {
        setGenerationState,
        clearGenerationState,
        nextGenerationId,
        buildGenerationHistory,
        cleanText
    } = services.lifecycle;

    const {
        inputValue,
        isImpersonating,
        isGenerating,
        currentMessages,
        activeChatChar,
        showBottomSheet,
        closeBottomSheet,
        openApiView,
        t
    } = services.state;

    const charId = char.id;

    let preset = null;
    try {
        const chatId = charId && char?.sessionId ? `${charId}_${char.sessionId}` : null;
        preset = getEffectivePreset(charId, chatId);
    } catch (e) { }

    const promptText = preset ? (preset.impersonationPrompt || '') : '';

    if (!promptText) {
        showBottomSheet({
