                description: t('impersonation_prompt_missing') || 'Impersonation prompt is empty',
                buttonText: t('btn_configure') || 'Configure',
                onButtonClick: () => {
                    closeBottomSheet();
                    openApiView();
                }
            }
        });
        return;
