    inputValue.value = '';

    isImpersonating.value = true;
    isGenerating.value = true;
    const genId = nextGenerationId();
    setGenerationState(charId, { genId, controller, type: 'impersonation' });

    const history = buildGenerationHistory(currentMessages);

    notifyGenerationStarted({ charId, sessionId: char.sessionId });

    return generateChat({
        text: promptText,
        char,
        history,
        guidanceText,
        type: 'impersonation',
        debugKey: `impersonation:${charId}:${char.sessionId || 'default'}:${genId}`,
        controller,
        callbacks: {
            onUpdate: (chunk) => { inputValue.value += chunk || ''; },
            onComplete: (response) => {
                inputValue.value = cleanText(response);
                isImpersonating.value = false;
                isGenerating.value = false;
                clearGenerationState(charId);
                notifyGenerationEnded({ charId });
            },
            onError: (err) => {
                console.error(err);
                isImpersonating.value = false;
                isGenerating.value = false;
                clearGenerationState(charId);
                notifyGenerationEnded({ charId });
            }
        }
    });
}

import { describe, it, expect, vi } from 'vitest';
import { applyRegexes } from '../regexService.js';

// Mock presetState
vi.mock('@/core/states/presetState.js', () => ({
    getEffectivePreset: vi.fn()
}));

describe('Regex Service', () => {
    // --- Basic Functionality ---

    it('applies basic replacement', () => {
        const scripts = [{
            id: '1',
            name: 'Test Replace',
            regex: 'apple',
            replacement: 'banana',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        const result = applyRegexes('I have an apple', 1, 1, { globalScripts: scripts });
        expect(result).toBe('I have an banana');
    });

    it('replaces all occurrences globally', () => {
        const scripts = [{
            id: '1',
            regex: 'cat',
            replacement: 'dog',
            placement: [1, 2],
            ephemerality: [1],
            disabled: false
        }];
        const result = applyRegexes('cat and cat and cat', 1, 1, { globalScripts: scripts });
        expect(result).toBe('dog and dog and dog');
    });

    it('returns empty string for empty/null input', () => {
        const scripts = [{
            id: '1',
            regex: 'test',
            replacement: 'ok',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        expect(applyRegexes('', 1, 1, { globalScripts: scripts })).toBe('');
        expect(applyRegexes(null, 1, 1, { globalScripts: scripts })).toBe('');
        expect(applyRegexes(undefined, 1, 1, { globalScripts: scripts })).toBe('');
    });

    // --- Trim Tokens ---

    it('handles trimOut (multiple lines)', () => {
        const scripts = [{
            id: '1',
            trimOut: 'bad\nugly',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        const result = applyRegexes('The bad and the ugly', 1, 1, { globalScripts: scripts });
        expect(result).toBe('The  and the ');
    });

    it('trimOut removes all occurrences', () => {
        const scripts = [{
            id: '1',
            trimOut: 'um',
            placement: [1, 2],
            ephemerality: [1],
            disabled: false
        }];
        const result = applyRegexes('um well um I think um', 1, 1, { globalScripts: scripts });
        expect(result).toBe(' well  I think ');
    });

    it('trimOut ignores empty lines', () => {
        const scripts = [{
            id: '1',
            trimOut: 'foo\n\n\nbar',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        const result = applyRegexes('foo and bar', 1, 1, { globalScripts: scripts });
        expect(result).toBe(' and ');
    });

    // --- Placement & Ephemerality Filters ---

    it('filters by placement and ephemerality', () => {
        const scripts = [{
            id: '1',
            regex: 'secret',
            replacement: 'REDACTED',
            placement: [2],       // AI Output only
            ephemerality: [2],    // Prompt only
            disabled: false
        }];

        // Should NOT match: placement=1 (User), ephemerality=2 (Prompt)
        expect(applyRegexes('secret', 1, 2, { globalScripts: scripts })).toBe('secret');

        // Should NOT match: placement=2 (AI), ephemerality=1 (Display)
        expect(applyRegexes('secret', 2, 1, { globalScripts: scripts })).toBe('secret');

        // Should match: placement=2, ephemerality=2
        expect(applyRegexes('secret', 2, 2, { globalScripts: scripts })).toBe('REDACTED');
    });

    it('applies to all placements when placement is not set', () => {
        const scripts = [{
            id: '1',
            regex: 'hello',
            replacement: 'hi',
            ephemerality: [1],
            disabled: false
        }];
        expect(applyRegexes('hello', 1, 1, { globalScripts: scripts })).toBe('hi');
        expect(applyRegexes('hello', 2, 1, { globalScripts: scripts })).toBe('hi');
    });

    it('applies to all ephemeralities when ephemerality is not set', () => {
        const scripts = [{
            id: '1',
            regex: 'hello',
            replacement: 'hi',
            placement: [1],
            disabled: false
        }];
        expect(applyRegexes('hello', 1, 1, { globalScripts: scripts })).toBe('hi');
        expect(applyRegexes('hello', 1, 2, { globalScripts: scripts })).toBe('hi');
    });

    // --- Disabled Scripts ---

    it('skips disabled scripts', () => {
        const scripts = [{
            id: '1',
            regex: 'test',
            replacement: 'passed',
            placement: [1],
            ephemerality: [1],
            disabled: true
        }];
        expect(applyRegexes('test', 1, 1, { globalScripts: scripts })).toBe('test');
    });

    // --- Error Handling ---

    it('handles invalid regex gracefully', () => {
        const scripts = [{
            id: '1',
            regex: '[',  // Invalid regex
            replacement: '!',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => { });
        const result = applyRegexes('test', 1, 1, { globalScripts: scripts });
        expect(result).toBe('test');
        expect(consoleSpy).toHaveBeenCalled();
        consoleSpy.mockRestore();
    });

    it('supports /pattern/flags format (ST compatible)', () => {
        const scripts = [{
            id: '1',
            regex: '/apple/i',
            replacement: 'banana',
            placement: [1],
            ephemerality: [1],
            disabled: false
        }];
        // Should match Case Insensitive
        expect(applyRegexes('I have an APPLE', 1, 1, { globalScripts: scripts })).toBe('I have an banana');

        // Should handle /s (dotAll) flag
        scripts[0].regex = '/a.b/s';
        scripts[0].replacement = 'match';
        expect(applyRegexes('a\nb', 1, 1, { globalScripts: scripts })).toBe('match');
    });

    // --- Chat Message Scenarios ---

    describe('Chat messages - AI Output display (placement=2, ephemerality=1)', () => {
        const placement = 2;
        const ephemerality = 1;

        it('strips OOC markers from AI response', () => {
            const scripts = [{
                id: '1',
                regex: '\\(OOC:.*?\\)',
                replacement: '',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const text = '*She smiles softly.* (OOC: I think we should continue the scene) "Hello!"';
            const result = applyRegexes(text, placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('*She smiles softly.*  "Hello!"');
        });

        it('replaces character name placeholder {{char}} in AI output', () => {
            const scripts = [{
                id: '1',
                regex: '\\{\\{char\\}\\}',
                replacement: 'Alice',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const text = '{{char}} walked into the room. "Hello," said {{char}}.';
            const result = applyRegexes(text, placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('Alice walked into the room. "Hello," said Alice.');
        });

        it('replaces {{user}} placeholder in AI output', () => {
            const scripts = [{
                id: '1',
                regex: '\\{\\{user\\}\\}',
                replacement: 'Bob',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const text = '"Nice to meet you, {{user}}," she said to {{user}}.';
            const result = applyRegexes(text, placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('"Nice to meet you, Bob," she said to Bob.');
        });

        it('removes reasoning/thinking blocks from display', () => {
            const scripts = [{
                id: '1',
                regex: '<thinking>[\\s\\S]*?</thinking>',
                replacement: '',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const text = '<thinking>I need to respond in character...</thinking>*She waves.* "Hey there!"';
            const result = applyRegexes(text, placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('*She waves.* "Hey there!"');
        });

        it('handles multiline AI output with regex', () => {
            const scripts = [{
                id: '1',
                regex: '\\[System Note:.*?\\]',
                replacement: '',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const text = '*She looks around.*\n[System Note: Stay in character]\n"Hello!"';
            const result = applyRegexes(text, placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('*She looks around.*\n\n"Hello!"');
        });
    });

    describe('Chat messages - User Input display (placement=1, ephemerality=1)', () => {
        const placement = 1;
        const ephemerality = 1;

        it('replaces {{user}} in user message for display', () => {
            const scripts = [{
                id: '1',
                regex: '\\{\\{user\\}\\}',
                replacement: 'Bob',
                placement: [1],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('I am {{user}}.', placement, ephemerality, { globalScripts: scripts });
            expect(result).toBe('I am Bob.');
        });
    });

    describe('Chat messages - Outgoing prompt (placement=2, ephemerality=2)', () => {
        const placement = 2;
        const ephemerality = 2;

        it('modifies AI text in outgoing prompt only', () => {
            const scripts = [{
                id: '1',
                regex: '\\bAlice\\b',
                replacement: '{{char}}',
                placement: [2],
                ephemerality: [2],
                disabled: false
            }];
            const text = 'Alice walked home.';
            // Should apply for prompt
            expect(applyRegexes(text, 2, 2, { globalScripts: scripts })).toBe('{{char}} walked home.');
            // Should NOT apply for display
            expect(applyRegexes(text, 2, 1, { globalScripts: scripts })).toBe('Alice walked home.');
        });
    });

    // --- Multiple Scripts ---

    describe('Multiple scripts', () => {
        it('applies scripts in order', () => {
            const scripts = [
                {
                    id: '1',
                    regex: 'aaa',
                    replacement: 'bbb',
                    placement: [1],
                    ephemerality: [1],
                    disabled: false
                },
                {
                    id: '2',
                    regex: 'bbb',
                    replacement: 'ccc',
                    placement: [1],
                    ephemerality: [1],
                    disabled: false
                }
            ];
            // aaa -> bbb -> ccc (second script transforms result of first)
            const result = applyRegexes('aaa', 1, 1, { globalScripts: scripts });
            expect(result).toBe('ccc');
        });

        it('applies both trimOut and regex from same script', () => {
            const scripts = [{
                id: '1',
                trimOut: 'REMOVE_ME',
                regex: 'foo',
                replacement: 'bar',
                placement: [1],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('REMOVE_ME foo test', 1, 1, { globalScripts: scripts });
            expect(result).toBe(' bar test');
        });

        it('mixed disabled and active scripts', () => {
            const scripts = [
                {
                    id: '1',
                    regex: 'hello',
                    replacement: 'HIDDEN',
                    placement: [1],
                    ephemerality: [1],
                    disabled: true
                },
                {
                    id: '2',
                    regex: 'world',
                    replacement: 'earth',
                    placement: [1],
                    ephemerality: [1],
                    disabled: false
                }
            ];
            const result = applyRegexes('hello world', 1, 1, { globalScripts: scripts });
            expect(result).toBe('hello earth');
        });
    });

    // --- Capture Groups ---

    describe('Capture groups in replacement', () => {
        it('supports $1 capture group in replacement', () => {
            const scripts = [{
                id: '1',
                regex: '\\*\\*(.*?)\\*\\*',
                replacement: '<b>$1</b>',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('She said **hello** loudly.', 2, 1, { globalScripts: scripts });
            expect(result).toBe('She said <b>hello</b> loudly.');
        });

        it('supports multiple capture groups', () => {
            const scripts = [{
                id: '1',
                regex: '(\\w+)@(\\w+)',
                replacement: '$1 at $2',
                placement: [1],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('Contact: user@domain', 1, 1, { globalScripts: scripts });
            expect(result).toBe('Contact: user at domain');
        });
    });

    // --- Edge Cases ---

    describe('Edge cases', () => {
        it('replacement with empty string (deletion)', () => {
            const scripts = [{
                id: '1',
                regex: '\\s+',
                replacement: '',
                placement: [1],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('h e l l o', 1, 1, { globalScripts: scripts });
            expect(result).toBe('hello');
        });

        it('handles special characters in replacement', () => {
            const scripts = [{
                id: '1',
                regex: 'plain',
                replacement: '<em>fancy</em>',
                placement: [2],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('A plain day.', 2, 1, { globalScripts: scripts });
            expect(result).toBe('A <em>fancy</em> day.');
        });

        it('regex with no replacement defaults to empty string', () => {
            const scripts = [{
                id: '1',
                regex: 'remove_this',
                placement: [1],
                ephemerality: [1],
                disabled: false
            }];
            const result = applyRegexes('keep remove_this text', 1, 1, { globalScripts: scripts });
            expect(result).toBe('keep  text');
        });

        it('handles no scripts gracefully', () => {
            const result = applyRegexes('hello world', 1, 1, { globalScripts: [] });
            expect(result).toBe('hello world');
        });
    });
});

import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { App } from '@capacitor/app';
import { db } from '@/utils/db.js';
import { DROPBOX_APP_KEY } from '@/core/config/syncConfig.js';
import { SYNC_TOKENS_KEY } from '@/core/states/syncState.js';

const REDIRECT_URI_NATIVE = import.meta.env.VITE_DROPBOX_REDIRECT_NATIVE || 'com.hydall.glaze://oauth/dropbox';
const REDIRECT_URI_WEB = import.meta.env.VITE_DROPBOX_REDIRECT_WEB || `${window.location.origin}/oauth/dropbox/redirect.html`;
const API_BASE = 'https://api.dropboxapi.com/2';
const CONTENT_BASE = 'https://content.dropboxapi.com/2';

function getRedirectUri() {
    if (Capacitor.isNativePlatform()) return REDIRECT_URI_NATIVE;
    if (isElectron()) return `http://127.0.0.1:${localStorage.getItem('gz_electron_oauth_port') || '0'}/oauth/callback`;
    return REDIRECT_URI_WEB;
}

function generateRandomString(length) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
    const array = crypto.getRandomValues(new Uint8Array(length));
    return Array.from(array, b => chars[b % chars.length]).join('');
}

async function sha256(text) {
    if (!crypto.subtle) return null;
    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hash = await crypto.subtle.digest('SHA-256', data);
    return btoa(String.fromCharCode(...new Uint8Array(hash)))
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function getTokens() {
    const all = await db.get(SYNC_TOKENS_KEY);
    if (!all) return null;
    return all.dropbox || null;
}

async function saveTokens(tokens) {
    const all = (await db.get(SYNC_TOKENS_KEY)) || {};
    all.dropbox = tokens;
    await db.queuedSet(SYNC_TOKENS_KEY, all);
}

async function clearTokens() {
    const all = (await db.get(SYNC_TOKENS_KEY)) || {};
    delete all.dropbox;
    await db.queuedSet(SYNC_TOKENS_KEY, all);
}

async function getValidToken() {
    const tokens = await getTokens();
    if (!tokens) return null;

    try {
        await listFolder('');
        return tokens.access_token;
    } catch (e) {
        if (e.status === 401 && tokens.refresh_token) {
            try {
                const refreshed = await refreshAccessToken(tokens.refresh_token);
                return refreshed.access_token;
            } catch {
                await clearTokens();
                return null;
            }
        }
        return null;
    }
}

async function refreshAccessToken(refreshToken) {
    if (!DROPBOX_APP_KEY) throw new Error('Dropbox app key not configured');

    const response = await fetch('https://api.dropboxapi.com/oauth2/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            grant_type: 'refresh_token',
            refresh_token: refreshToken,
            client_id: DROPBOX_APP_KEY
        })
    });

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw Object.assign(new Error(err.error_description || 'Token refresh failed'), { status: response.status });
    }

    const data = await response.json();
    const newTokens = {
        access_token: data.access_token,
        refresh_token: refreshToken,
        expires_at: Date.now() + (data.expires_in || 14400) * 1000,
        account_id: data.account_id
    };
    await saveTokens(newTokens);
    return newTokens;
}

export async function connect() {
    if (!DROPBOX_APP_KEY) {
        throw new Error('Dropbox is not configured. Set VITE_DROPBOX_APP_KEY environment variable.');
    }

    const verifier = generateRandomString(64);
    const challenge = await sha256(verifier);
    const usePlain = !challenge;
    const redirectUri = getRedirectUri();
    const state = generateRandomString(16);

    localStorage.setItem('gz_dropbox_pkce_verifier', verifier);
    localStorage.setItem('gz_dropbox_pkce_state', state);

    const authUrl = new URL('https://www.dropbox.com/oauth2/authorize');
    authUrl.searchParams.set('client_id', DROPBOX_APP_KEY);
    authUrl.searchParams.set('response_type', 'code');
    authUrl.searchParams.set('code_challenge', usePlain ? verifier : challenge);
    authUrl.searchParams.set('code_challenge_method', usePlain ? 'plain' : 'S256');
    authUrl.searchParams.set('redirect_uri', redirectUri);
    authUrl.searchParams.set('token_access_type', 'offline');
    authUrl.searchParams.set('state', state);

    if (Capacitor.isNativePlatform()) {
        const listener = await App.addListener('appUrlOpen', async (data) => {
            try {
                const url = new URL(data.url);
                const code = url.searchParams.get('code');
                const returnedState = url.searchParams.get('state');

                if (!code) return;

                if (returnedState !== state) {
                    console.error('[dropboxAdapter] State mismatch');
                    return;
                }

                await exchangeCodeForToken(code, verifier, redirectUri);
            } catch (e) {
                console.error('[dropboxAdapter] OAuth callback error:', e);
            } finally {
                listener.remove();
                try { await Browser.close(); } catch {}
            }
        });

        await Browser.open({ url: authUrl.toString() });
    } else if (isElectron()) {
        const code = await waitForElectronOAuth(redirectUri, state);
        if (code) {
            await exchangeCodeForToken(code, verifier, redirectUri);
        } else {
            throw new Error('Authorization cancelled');
        }
    } else {
        const code = await waitForWebOAuth(authUrl.toString(), state);
        if (code) {
            await exchangeCodeForToken(code, verifier, redirectUri);
        } else {
            throw new Error('Authorization cancelled');
        }
    }
}

function isElectron() {
    return typeof navigator !== 'undefined' && navigator.userAgent.includes('Electron');
}

async function waitForElectronOAuth(redirectUri, expectedState) {
    const ipcRenderer = window.require('electron').ipcRenderer;
    const port = await ipcRenderer.invoke('oauth-start-server');
    redirectUri = `http://127.0.0.1:${port}/oauth/callback`;

    const authUrl = new URL('https://www.dropbox.com/oauth2/authorize');
    authUrl.searchParams.set('client_id', DROPBOX_APP_KEY);
    authUrl.searchParams.set('response_type', 'code');
    authUrl.searchParams.set('code_challenge', localStorage.getItem('gz_dropbox_pkce_verifier'));
    authUrl.searchParams.set('code_challenge_method', 'plain');
    authUrl.searchParams.set('redirect_uri', redirectUri);
    authUrl.searchParams.set('token_access_type', 'offline');
    authUrl.searchParams.set('state', expectedState);

    const width = 500;
    const height = 600;
    const left = window.screenX + (window.outerWidth - width) / 2;
    const top = window.screenY + (window.outerHeight - height) / 2;
    const win = window.open(authUrl.toString(), 'dropbox-auth', `width=${width},height=${height},left=${left},top=${top}`);

    return new Promise((resolve) => {
        let resolved = false;
        let interval;
        const cleanup = () => clearInterval(interval);

        ipcRenderer.once('oauth-callback', (event, { code, state: returnedState, error }) => {
            if (resolved) return;
            resolved = true;
            cleanup();
            try { if (win && !win.closed) win.close(); } catch {}

            if (error || !code) { resolve(null); return; }
            if (returnedState !== expectedState) {
                console.error('[dropboxAdapter] State mismatch');
                resolve(null);
                return;
            }
            resolve(code);
        });

        interval = setInterval(() => {
            if (resolved) return;
            try {
                if (win && win.closed) {
                    resolved = true;
                    cleanup();
                    ipcRenderer.invoke('oauth-cancel-server');
                    resolve(null);
                }
            } catch {
                resolved = true;
                cleanup();
                resolve(null);
            }
        }, 1000);
    });
}

function waitForWebOAuth(authUrl, expectedState) {
    return new Promise((resolve) => {
        const width = 500;
        const height = 600;
        const left = window.screenX + (window.outerWidth - width) / 2;
        const top = window.screenY + (window.outerHeight - height) / 2;
        const win = window.open(authUrl, 'dropbox-auth', `width=${width},height=${height},left=${left},top=${top}`);

        let resolved = false;
        let interval;

        const cleanup = () => {
            clearInterval(interval);
            window.removeEventListener('message', onMessage);
        };

        function onMessage(e) {
            if (resolved) return;
            if (e.data?.type === 'dropbox-oauth') {
                resolved = true;
                cleanup();
                const state = e.data.state;
                if (state !== expectedState) {
                    console.error('[dropboxAdapter] State mismatch');
                    resolve(null);
                    return;
                }
                resolve(e.data.code || null);
            }
        }

        interval = setInterval(() => {
            if (resolved) return;
            try {
                if (win.closed) {
                    cleanup();
                    resolve(null);
                }
            } catch {
                cleanup();
                resolve(null);
            }
        }, 1000);

        window.addEventListener('message', onMessage);
    });
}

async function exchangeCodeForToken(code, verifier, redirectUri) {
    const response = await fetch('https://api.dropboxapi.com/oauth2/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            grant_type: 'authorization_code',
            code,
            code_verifier: verifier,
            client_id: DROPBOX_APP_KEY,
            redirect_uri: redirectUri
        })
    });

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.error_description || 'Token exchange failed');
    }

    const data = await response.json();
    await saveTokens({
        access_token: data.access_token,
        refresh_token: data.refresh_token,
        expires_at: Date.now() + (data.expires_in || 14400) * 1000,
        account_id: data.account_id,
        uid: data.uid
    });

    localStorage.removeItem('gz_dropbox_pkce_verifier');
    localStorage.removeItem('gz_dropbox_pkce_state');

    await ensureFolder('/Glaze');
}

export async function disconnect() {
    const tokens = await getTokens();
    if (tokens?.access_token) {
        try {
            await fetch('https://api.dropboxapi.com/2/auth/token/revoke', {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${tokens.access_token}` }
            });
        } catch {}
    }
    await clearTokens();
}

export async function isConnected() {
    const tokens = await getTokens();
    if (!tokens) return false;
    const valid = await getValidToken();
    return valid !== null;
}

async function apiCall(endpoint, body, accessToken) {
    if (!accessToken) {
        const tokens = await getTokens();
        if (!tokens) throw new Error('Not connected to Dropbox');
        accessToken = tokens.access_token;
    }

    const response = await fetch(`${API_BASE}${endpoint}`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
    });

    if (response.status === 401) {
        const tokens = await getTokens();
        if (tokens?.refresh_token) {
            const refreshed = await refreshAccessToken(tokens.refresh_token);
            return apiCall(endpoint, body, refreshed.access_token);
        }
        throw Object.assign(new Error('Session expired'), { status: 401 });
    }

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw Object.assign(new Error(err.error?.tag || err.error_summary || `API error ${response.status}`), { status: response.status });
    }

    if (response.status === 204) return null;
    return response.json();
}

async function contentUpload(path, data, accessToken) {
    if (!accessToken) {
        const tokens = await getTokens();
        if (!tokens) throw new Error('Not connected to Dropbox');
        accessToken = tokens.access_token;
    }

    const body = typeof data === 'string' ? data : JSON.stringify(data);

    const response = await fetch(`${CONTENT_BASE}/files/upload`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Content-Type': 'application/octet-stream',
            'Dropbox-API-Arg': JSON.stringify({
                path,
                mode: 'overwrite',
                autorename: false,
                mute: true
            })
        },
        body
    });

    if (response.status === 401) {
        const tokens = await getTokens();
        if (tokens?.refresh_token) {
            const refreshed = await refreshAccessToken(tokens.refresh_token);
            return contentUpload(path, data, refreshed.access_token);
        }
        throw Object.assign(new Error('Session expired'), { status: 401 });
    }

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw Object.assign(new Error(err.error?.tag || err.error_summary || `Upload failed ${response.status}`), { status: response.status });
    }

    return response.json();
}

async function contentDownload(path, accessToken) {
    if (!accessToken) {
        const tokens = await getTokens();
        if (!tokens) throw new Error('Not connected to Dropbox');
        accessToken = tokens.access_token;
    }

    const response = await fetch(`${CONTENT_BASE}/files/download`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Dropbox-API-Arg': JSON.stringify({ path })
        }
    });

    if (response.status === 401) {
        const tokens = await getTokens();
        if (tokens?.refresh_token) {
            const refreshed = await refreshAccessToken(tokens.refresh_token);
            return contentDownload(path, refreshed.access_token);
        }
        throw Object.assign(new Error('Session expired'), { status: 401 });
    }

    if (response.status === 409) {
        return null;
    }

    if (!response.ok) {
        throw Object.assign(new Error(`Download failed ${response.status}`), { status: response.status });
    }

    const metadata = JSON.parse(response.headers.get('dropbox-api-result') || '{}');
    const text = await response.text();
    return { data: text, metadata };
}

const APP_FOLDER_PREFIX = '/Glaze';

function stripAppFolderPrefix(path) {
    if (path === APP_FOLDER_PREFIX || path === APP_FOLDER_PREFIX + '/') return '';
    if (path.startsWith(APP_FOLDER_PREFIX + '/')) return path.slice(APP_FOLDER_PREFIX.length);
    return path;
}

export async function ensureFolder(path) {
    const strippedPath = stripAppFolderPrefix(path);
    const parts = strippedPath.split('/').filter(Boolean);
    if (parts.length === 0) return;
    let currentPath = '';
    for (const part of parts) {
        currentPath = currentPath + '/' + part;
        try {
            await apiCall('/files/create_folder_v2', { path: currentPath, autorename: false });
        } catch (e) {
            if (e.message?.includes('conflict') || e.message?.includes('already_exists')) {
                continue;
            }
            throw e;
        }
    }
}

export async function listFolder(path) {
    return apiCall('/files/list_folder', { path: stripAppFolderPrefix(path) || '', recursive: false, include_deleted: false });
}

export async function listFolderContinue(cursor) {
    return apiCall('/files/list_folder/continue', { cursor });
}

export async function upload(path, data) {
    return contentUpload(stripAppFolderPrefix(path), data);
}

export async function download(path) {
    return contentDownload(stripAppFolderPrefix(path));
}

export async function deleteFile(fileOrPath) {
    const path = typeof fileOrPath === 'string'
        ? fileOrPath
        : (fileOrPath?.path_display || fileOrPath?.path || '');
    return apiCall('/files/delete_v2', { path: stripAppFolderPrefix(path) });
}

export async function getAccountInfo() {
    const tokens = await getTokens();
    if (!tokens) return null;
    try {
        const result = await apiCall('/users/get_current_account', null, tokens.access_token);
        return {
            name: result.name?.display_name || 'Dropbox User',
            email: result.email,
            accountId: result.account_id
        };
    } catch {
        return null;
    }
}

import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { App } from '@capacitor/app';
import { db } from '@/utils/db.js';
import { GDRIVE_CLIENT_ID, GDRIVE_CLIENT_SECRET } from '@/core/config/syncConfig.js';
import { SYNC_TOKENS_KEY } from '@/core/states/syncState.js';

const getNativeRedirectUri = () => {
    if (import.meta.env.VITE_GDRIVE_REDIRECT_NATIVE) return import.meta.env.VITE_GDRIVE_REDIRECT_NATIVE;
    if (GDRIVE_CLIENT_ID && GDRIVE_CLIENT_ID.endsWith('.apps.googleusercontent.com')) {
        return GDRIVE_CLIENT_ID.split('.').reverse().join('.') + ':/oauth2redirect';
    }
    return 'com.hydall.glaze://oauth/gdrive';
};
const REDIRECT_URI_NATIVE = getNativeRedirectUri();
const REDIRECT_URI_WEB = import.meta.env.VITE_GDRIVE_REDIRECT_WEB || `${window.location.origin}/oauth/gdrive/redirect.html`;
const API_BASE = 'https://www.googleapis.com/drive/v3';
const UPLOAD_BASE = 'https://www.googleapis.com/upload/drive/v3';
const AUTH_BASE = 'https://accounts.google.com/o/oauth2/v2/auth';
const TOKEN_URL = 'https://oauth2.googleapis.com/token';

const SCOPES = 'https://www.googleapis.com/auth/drive.file';

const FOLDER_NAME = 'Glaze';
let folderIdCache = null;

function getRedirectUri() {
    if (Capacitor.isNativePlatform()) return REDIRECT_URI_NATIVE;
    if (isElectron()) return `http://127.0.0.1:${localStorage.getItem('gz_electron_oauth_port') || '0'}/oauth/callback`;
    return REDIRECT_URI_WEB;
}

function generateRandomString(length) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
    const array = crypto.getRandomValues(new Uint8Array(length));
    return Array.from(array, b => chars[b % chars.length]).join('');
}

async function sha256(text) {
    if (!crypto.subtle) return null;
    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hash = await crypto.subtle.digest('SHA-256', data);
    return btoa(String.fromCharCode(...new Uint8Array(hash)))
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function getTokens() {
    const all = await db.get(SYNC_TOKENS_KEY);
    if (!all) return null;
    return all.gdrive || null;
}

async function saveTokens(tokens) {
    const all = (await db.get(SYNC_TOKENS_KEY)) || {};
    all.gdrive = tokens;
    await db.queuedSet(SYNC_TOKENS_KEY, all);
}

async function clearTokens() {
    const all = (await db.get(SYNC_TOKENS_KEY)) || {};
    delete all.gdrive;
    await db.queuedSet(SYNC_TOKENS_KEY, all);
}

async function refreshAccessToken(refreshToken) {
    if (!GDRIVE_CLIENT_ID) throw new Error('Google Drive client ID not configured');

    const params = {
        grant_type: 'refresh_token',
        refresh_token: refreshToken,
        client_id: GDRIVE_CLIENT_ID,
        ...(GDRIVE_CLIENT_SECRET && { client_secret: GDRIVE_CLIENT_SECRET })
    };

    const response = await fetch(TOKEN_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams(params)
    });

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw Object.assign(new Error(err.error_description || 'Token refresh failed'), { status: response.status });
    }

    const data = await response.json();
    const newTokens = {
        access_token: data.access_token,
        refresh_token: refreshToken,
        expires_at: Date.now() + (data.expires_in || 3600) * 1000
    };
    await saveTokens(newTokens);
    return newTokens;
}

async function getValidAccessToken() {
    const tokens = await getTokens();
    if (!tokens) return null;

    if (tokens.expires_at && Date.now() < tokens.expires_at - 60000) {
        return tokens.access_token;
    }

    if (tokens.refresh_token) {
        try {
            const refreshed = await refreshAccessToken(tokens.refresh_token);
            return refreshed.access_token;
        } catch {
            await clearTokens();
            return null;
        }
    }

    return null;
}

async function apiRequest(url, options = {}) {
    const accessToken = await getValidAccessToken();
    if (!accessToken) throw new Error('Not connected to Google Drive');

    const headers = {
        'Authorization': `Bearer ${accessToken}`,
        ...options.headers
    };

    const response = await fetch(url, { ...options, headers });

    if (response.status === 401) {
        const tokens = await getTokens();
        if (tokens?.refresh_token) {
            const refreshed = await refreshAccessToken(tokens.refresh_token);
            headers.Authorization = `Bearer ${refreshed.access_token}`;
            return fetch(url, { ...options, headers });
        }
        throw Object.assign(new Error('Session expired'), { status: 401 });
    }

    return response;
}

export async function connect() {
    if (!GDRIVE_CLIENT_ID) {
        throw new Error('Google Drive is not configured. Set VITE_GDRIVE_CLIENT_ID environment variable.');
    }

    const verifier = generateRandomString(64);
    const challenge = await sha256(verifier);
    const usePlain = !challenge;
    const state = generateRandomString(16);

    localStorage.setItem('gz_gdrive_pkce_verifier', verifier);
    localStorage.setItem('gz_gdrive_pkce_state', state);

    if (isElectron()) {
        const result = await waitForElectronOAuth(challenge, usePlain, state, verifier);
        if (result) {
            await exchangeCodeForToken(result.code, verifier, result.redirectUri);
        } else {
            throw new Error('Authorization cancelled');
        }
        return;
    }

    const redirectUri = getRedirectUri();
    const authUrl = new URL(AUTH_BASE);
    authUrl.searchParams.set('client_id', GDRIVE_CLIENT_ID);
    authUrl.searchParams.set('redirect_uri', redirectUri);
    authUrl.searchParams.set('response_type', 'code');
    authUrl.searchParams.set('scope', SCOPES);
    authUrl.searchParams.set('code_challenge', usePlain ? verifier : challenge);
    authUrl.searchParams.set('code_challenge_method', usePlain ? 'plain' : 'S256');
    authUrl.searchParams.set('state', state);
    authUrl.searchParams.set('access_type', 'offline');
    authUrl.searchParams.set('prompt', 'consent');

    if (Capacitor.isNativePlatform()) {
        await new Promise((resolve, reject) => {
            App.addListener('appUrlOpen', async (data) => {
                try {
                    const url = new URL(data.url);
                    const code = url.searchParams.get('code');
                    const returnedState = url.searchParams.get('state');

                    if (!code) return;

                    if (returnedState !== state) {
                        reject(new Error('State mismatch'));
                        return;
                    }

                    await exchangeCodeForToken(code, verifier, redirectUri);
                    resolve();
                } catch (e) {
                    reject(e);
                } finally {
                    try { await Browser.close(); } catch { }
                }
            }).then(listener => {
                Browser.open({ url: authUrl.toString() }).catch(reject);
            });
        });
    } else {
        const code = await waitForWebOAuth(authUrl.toString(), state);
        if (code) {
            await exchangeCodeForToken(code, verifier, redirectUri);
        } else {
            throw new Error('Authorization cancelled');
        }
    }
}

function isElectron() {
    return typeof navigator !== 'undefined' && navigator.userAgent.includes('Electron');
}

async function waitForElectronOAuth(challenge, usePlain, state, verifier) {
    const ipcRenderer = window.require('electron').ipcRenderer;
    const port = await ipcRenderer.invoke('oauth-start-server');
    const redirectUri = `http://127.0.0.1:${port}/oauth/callback`;

    const authUrl = new URL(AUTH_BASE);
    authUrl.searchParams.set('client_id', GDRIVE_CLIENT_ID);
    authUrl.searchParams.set('redirect_uri', redirectUri);
    authUrl.searchParams.set('response_type', 'code');
    authUrl.searchParams.set('scope', SCOPES);
    authUrl.searchParams.set('code_challenge', usePlain ? verifier : challenge);
    authUrl.searchParams.set('code_challenge_method', usePlain ? 'plain' : 'S256');
    authUrl.searchParams.set('state', state);
    authUrl.searchParams.set('access_type', 'offline');
    authUrl.searchParams.set('prompt', 'consent');

    const width = 500;
    const height = 600;
    const left = window.screenX + (window.outerWidth - width) / 2;
    const top = window.screenY + (window.outerHeight - height) / 2;
    const win = window.open(authUrl.toString(), 'gdrive-auth', `width=${width},height=${height},left=${left},top=${top}`);

    return new Promise((resolve) => {
        let resolved = false;
        let interval;
        const cleanup = () => clearInterval(interval);

        ipcRenderer.once('oauth-callback', (event, { code, state: returnedState, error }) => {
            if (resolved) return;
            resolved = true;
            cleanup();
            try { if (win && !win.closed) win.close(); } catch { }

            if (error || !code) { resolve(null); return; }
            if (returnedState !== state) {
                console.error('[gdriveAdapter] State mismatch');
                resolve(null);
                return;
            }
            resolve({ code, redirectUri });
        });

        interval = setInterval(() => {
            if (resolved) return;
            try {
                if (win && win.closed) {
                    resolved = true;
                    cleanup();
                    ipcRenderer.invoke('oauth-cancel-server');
                    resolve(null);
                }
            } catch {
                resolved = true;
                cleanup();
                resolve(null);
            }
        }, 1000);
    });
}

function waitForWebOAuth(authUrl, expectedState) {
    return new Promise((resolve) => {
        const width = 500;
        const height = 600;
        const left = window.screenX + (window.outerWidth - width) / 2;
        const top = window.screenY + (window.outerHeight - height) / 2;
        const win = window.open(authUrl, 'gdrive-auth', `width=${width},height=${height},left=${left},top=${top}`);

        let resolved = false;
        let interval;
        let onMessage;

        const cleanup = () => {
            clearInterval(interval);
            window.removeEventListener('message', onMessage);
        };

        onMessage = (e) => {
            if (resolved) return;
            if (e.data?.type === 'gdrive-oauth') {
                resolved = true;
                cleanup();
                const state = e.data.state;
                if (state !== expectedState) {
                    console.error('[gdriveAdapter] State mismatch');
                    resolve(null);
                    return;
                }
                resolve(e.data.code || null);
            }
        };

        interval = setInterval(() => {
            if (resolved) return;
            try {
                if (win.closed) {
                    cleanup();
                    resolve(null);
                }
            } catch {
                cleanup();
                resolve(null);
            }
        }, 1000);

        window.addEventListener('message', onMessage);
    });
}

async function exchangeCodeForToken(code, verifier, redirectUri) {
    const params = {
        grant_type: 'authorization_code',
        code,
        code_verifier: verifier,
        client_id: GDRIVE_CLIENT_ID,
        redirect_uri: redirectUri,
        ...(GDRIVE_CLIENT_SECRET && { client_secret: GDRIVE_CLIENT_SECRET })
    };

    const response = await fetch(TOKEN_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams(params)
    });

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.error_description || 'Token exchange failed');
    }

    const data = await response.json();
    await saveTokens({
        access_token: data.access_token,
        refresh_token: data.refresh_token,
        expires_at: Date.now() + (data.expires_in || 3600) * 1000,
        token_type: data.token_type
    });

    localStorage.removeItem('gz_gdrive_pkce_verifier');
    localStorage.removeItem('gz_gdrive_pkce_state');

    folderIdCache = null;
    await ensureFolder('/Glaze');
}

export async function disconnect() {
    const tokens = await getTokens();
    if (tokens?.access_token) {
        try {
            await fetch(`https://oauth2.googleapis.com/revoke?token=${tokens.access_token}`, {
                method: 'POST'
            });
        } catch { }
    }
    await clearTokens();
    folderIdCache = null;
}

export async function isConnected() {
    const token = await getValidAccessToken();
    return token !== null;
}

async function findFolderByName(name, parentId) {
    let query = `name='${name}' and mimeType='application/vnd.google-apps.folder' and trashed=false`;
    if (parentId) {
        query += ` and '${parentId}' in parents`;
    } else {
        query += ` and 'root' in parents`;
    }

    const response = await apiRequest(
        `${API_BASE}/files?q=${encodeURIComponent(query)}&spaces=drive&fields=files(id,name)`
    );

    if (!response.ok) return null;
    const data = await response.json();
    return data.files?.[0]?.id || null;
}

async function createFolder(name, parentId) {
    const body = {
        name,
        mimeType: 'application/vnd.google-apps.folder'
    };
    if (parentId) {
        body.parents = [parentId];
    }

    const response = await apiRequest(`${API_BASE}/files?fields=id`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    });

    if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.error?.message || 'Failed to create folder');
    }

    const data = await response.json();
    return data.id;
}

async function getOrCreateFolder(name, parentId) {
    const existingId = await findFolderByName(name, parentId);
    if (existingId) return existingId;
    return createFolder(name, parentId);
}

export async function ensureFolder(path) {
    const parts = path.split('/').filter(Boolean);
    let parentId = null;

    for (const part of parts) {
        const folderId = await getOrCreateFolder(part, parentId);
        parentId = folderId;
    }

    if (path === '/Glaze') {
        folderIdCache = parentId;
    }

    return parentId;
}

async function getGlazeFolderId() {
    if (folderIdCache) return folderIdCache;
    folderIdCache = await findFolderByName(FOLDER_NAME, null);
    if (!folderIdCache) {
        folderIdCache = await createFolder(FOLDER_NAME, null);
    }
    return folderIdCache;
}

async function resolvePathToParent(path) {
    const parts = path.replace(/^\//, '').split('/');
    const fileName = parts.pop();
    let parentId = await getGlazeFolderId();

    for (const dir of parts) {
        if (dir === FOLDER_NAME) continue;
        parentId = await getOrCreateFolder(dir, parentId);
    }

    return { parentId, fileName };
}

async function findFileByName(name, parentId) {
    const query = `name='${name}' and '${parentId}' in parents and trashed=false`;
    const response = await apiRequest(
        `${API_BASE}/files?q=${encodeURIComponent(query)}&spaces=drive&fields=files(id,name,modifiedTime)`
    );

    if (!response.ok) return null;
    const data = await response.json();
    return data.files?.[0] || null;
}

export async function upload(path, data) {
    const { parentId, fileName } = await resolvePathToParent(path);
    const existingFile = await findFileByName(fileName, parentId);

    const body = typeof data === 'string' ? data : JSON.stringify(data);

    if (existingFile) {
        const response = await apiRequest(
            `${UPLOAD_BASE}/files/${existingFile.id}?uploadType=media`,
            {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/octet-stream' },
                body
            }
        );

        if (!response.ok) {
            const err = await response.json().catch(() => ({}));
            throw new Error(err.error?.message || `Upload failed ${response.status}`);
        }

        return response.json();
    } else {
        const metadata = {
            name: fileName,
            parents: [parentId]
        };

        const boundary = 'glaze_boundary_' + generateRandomString(16);
        const multipartBody =
            `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n` +
            `--${boundary}\r\nContent-Type: application/octet-stream\r\n\r\n${body}\r\n` +
            `--${boundary}--`;

        const response = await apiRequest(
            `${UPLOAD_BASE}/files?uploadType=multipart&fields=id`,
            {
                method: 'POST',
                headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
                body: multipartBody
            }
        );

        if (!response.ok) {
            const err = await response.json().catch(() => ({}));
            throw new Error(err.error?.message || `Upload failed ${response.status}`);
        }

        return response.json();
    }
}

export async function download(path) {
    const { parentId, fileName } = await resolvePathToParent(path);
    const file = await findFileByName(fileName, parentId);

    if (!file) return null;

    const response = await apiRequest(
        `${API_BASE}/files/${file.id}?alt=media`
    );

    if (!response.ok) {
        if (response.status === 404) return null;
        throw new Error(`Download failed ${response.status}`);
    }

    const text = await response.text();
    return {
        data: text,
        metadata: { id: file.id, modifiedTime: file.modifiedTime }
    };
}

export async function listFolder(path) {
    const parts = path.replace(/^\//, '').split('/').filter(Boolean);
    let parentId = null;

    if (parts.length === 0 || (parts.length === 1 && parts[0] === FOLDER_NAME)) {
        parentId = await getGlazeFolderId();
    } else {
        const folderName = parts[parts.length - 1];
        const parentPath = '/' + parts.slice(0, -1).join('/');
        const { parentId: resolvedParent } = await resolvePathToParent(parentPath || `/${FOLDER_NAME}`);
        const folder = await findFolderByName(folderName, resolvedParent);
        parentId = folder;
    }

    if (!parentId) return { entries: [] };

    const query = `'${parentId}' in parents and trashed=false`;
    const response = await apiRequest(
        `${API_BASE}/files?q=${encodeURIComponent(query)}&spaces=drive&fields=files(id,name,mimeType,modifiedTime)&pageSize=1000`
    );

    if (!response.ok) return { entries: [] };

    const data = await response.json();
    const entries = (data.files || []).map(f => ({
        '.tag': f.mimeType === 'application/vnd.google-apps.folder' ? 'folder' : 'file',
        name: f.name,
        path: path === '/Glaze' ? `/Glaze/${f.name}` : `${path}/${f.name}`,
        path_display: path === '/Glaze' ? `/Glaze/${f.name}` : `${path}/${f.name}`,
        serverModified: f.modifiedTime,
        id: f.id
    }));

    return { entries, has_more: false };
}

export async function listFolderContinue() {
    return { entries: [], has_more: false };
}

export async function deleteFile(fileOrPath) {
    let fileId = null;

    if (typeof fileOrPath === 'object' && fileOrPath?.id) {
        fileId = fileOrPath.id;
    } else {
        const path = typeof fileOrPath === 'string'
            ? fileOrPath
            : (fileOrPath?.path_display || fileOrPath?.path || '');
        const { parentId, fileName } = await resolvePathToParent(path);
        const file = await findFileByName(fileName, parentId);
        if (!file) return null;
        fileId = file.id;
    }

    const response = await apiRequest(
        `${API_BASE}/files/${fileId}`,
        { method: 'DELETE' }
    );

    if (!response.ok && response.status !== 204) {
        throw new Error(`Delete failed ${response.status}`);
    }

    return null;
}

export async function getAccountInfo() {
    const accessToken = await getValidAccessToken();
    if (!accessToken) return null;

    try {
        const response = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', {
            headers: { 'Authorization': `Bearer ${accessToken}` }
        });

        if (!response.ok) return null;
        const data = await response.json();
        return {
            name: data.name || 'Google User',
            email: data.email,
            accountId: data.id
        };
    } catch {
