    if (document.visibilityState === 'visible') {
        const activeContext = getActiveContext();
        if (String(activeContext.charId) === String(charId) && String(activeContext.sessionId) === String(sessionId)) {
            return;
        }
    }

    logger.debug("[NotificationService] Sending notification for charId:", charId);

    if (!charId) {
        console.warn("[NotificationService] Warning: charId is missing/undefined!");
    }

    try {
        if (Capacitor.getPlatform() === 'android') {
            let avatarBase64 = null;
            if (icon) {
                const cacheKey = `${charId || 'unknown'}:${icon}`;
                if (avatarBase64Cache.has(cacheKey)) {
                    avatarBase64 = avatarBase64Cache.get(cacheKey);
                }
                let url = icon;
                if (!url.startsWith('http') && !url.startsWith('data:') && !url.startsWith('blob:')) {
                    url = `/characters/${url}`;
                }
                if (!avatarBase64) {
                    try {
                        const res = await fetch(url);
                        const blob = await res.blob();
                        await new Promise((resolve) => {
                            const reader = new FileReader();
                            reader.onloadend = () => {
                                avatarBase64 = reader.result;
                                resolve();
                            };
                            reader.readAsDataURL(blob);
                        });
                        if (avatarBase64) {
                            avatarBase64Cache.set(cacheKey, avatarBase64);
                        }
                    } catch (e) { console.warn("Failed to convert avatar to base64", e); }
                }
            }

            await MessagingStyleNotification.showMessagingNotification({
                title,
                body,
                avatarBase64,
                charId: String(charId || ''),
                sessionId: String(sessionId || ''),
                msgId: String(msgId || '')
            });
        } else if (window.Notification && Notification.permission === 'granted') {
            let iconPath = icon;
            if (iconPath && !iconPath.startsWith('http') && !iconPath.startsWith('data:') && !iconPath.startsWith('blob:')) {
                iconPath = `/characters/${iconPath}`;
            }

            const n = new Notification(title, {
                body: body,
                icon: iconPath,
                data: { charId, sessionId, msgId }
            });
            n.onclick = () => {
                window.focus();
                if (charId) window.dispatchEvent(new CustomEvent('open-chat', { detail: { charId, sessionId, msgId } }));
                n.close();
            };
        }
    } catch (e) {
        console.error("Error sending notification:", e);
    }
}

export function generateId(length = 6) {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, length);
}

export function detectPresetFormat(data) {
    if (data.tabs && Array.isArray(data.tabs)) return 'latex';
    if (data.prompts && Array.isArray(data.prompts)) return 'sillytavern';
    if (data.blocks && Array.isArray(data.blocks)) return 'glaze';
    return null;
}

export function finalizeImportedPreset(preset) {
    if (!preset.blocks) preset.blocks = [];

    preset.blocks.forEach(b => {
        if (b.id !== 'authors_note' && b.id !== 'summary' && !b.insertion_mode) {
            b.insertion_mode = 'relative';
        }
    });

    if (!preset.blocks.find(b => b.id === 'summary')) {
        const historyIdx = preset.blocks.findIndex(b => b.id === 'chat_history');
        const insertIdx = historyIdx !== -1 ? historyIdx : preset.blocks.length;
        preset.blocks.splice(insertIdx, 0, { id: 'summary', name: 'Summary', role: 'system', content: '', enabled: true, isStatic: true, i18n: 'magic_summary', depth: 4, insertion_mode: 'relative', prefix: 'Summary: ' });
    }
    if (!preset.blocks.find(b => b.id === 'authors_note')) {
        const historyIdx = preset.blocks.findIndex(b => b.id === 'chat_history');
        const insertIdx = historyIdx !== -1 ? historyIdx + 1 : preset.blocks.length;
        preset.blocks.splice(insertIdx, 0, { id: 'authors_note', name: "Author's Note", role: 'system', content: '', enabled: true, isStatic: true, i18n: 'magic_authors_notes', insertion_mode: 'relative' });
    }
    if (!preset.blocks.find(b => b.id === 'guided_generation')) {
        const authorsIdx = preset.blocks.findIndex(b => b.id === 'authors_note');
        const historyIdx = preset.blocks.findIndex(b => b.id === 'chat_history');
        const insertIdx = authorsIdx !== -1 ? authorsIdx + 1 : (historyIdx !== -1 ? historyIdx + 1 : preset.blocks.length);
        preset.blocks.splice(insertIdx, 0, { id: 'guided_generation', name: 'Guided Generation', role: 'system', content: '[System Note: {{guidance}}]', enabled: true, isStatic: true, i18n: 'block_guided_generation', insertion_mode: 'relative' });
    }

    if (!preset.guidedGenerationPrompt) preset.guidedGenerationPrompt = '[Generate your next reply according to these instructions: {{guidance}}]';
    if (!preset.guidedImpersonationPrompt) preset.guidedImpersonationPrompt = '[Instead of replying for {{char}}, impersonate {{user}} according to these instructions: {{guidance}}]';
    if (!preset.summaryPrompt) {
        preset.summaryPrompt = 'Summarize the following roleplay conversation concisely, focusing on the current situation and key events:\n\n{{history}}\n\nSummary:';
    }

    const newId = Date.now().toString();
    preset.id = newId;
    if (preset.createdAt === undefined) preset.createdAt = Date.now();
    return preset;
}

export const mandatoryBlocks = [
    { id: "worldInfoBefore", i18n: "block_wi_before", name: "World Info Before", role: "system", content: "", isStatic: true, enabled: true },
    { id: "user_persona", i18n: "block_user_persona", name: "User Persona", role: "system", content: "", isStatic: true, enabled: true },
    { id: "char_card", i18n: "block_char_card", name: "Character Card", role: "system", content: "", isStatic: true, enabled: true },
    { id: "char_personality", i18n: "block_char_personality", name: "Character Personality", role: "system", content: "", isStatic: true, enabled: true },
    { id: "scenario", i18n: "block_scenario", name: "Scenario", role: "system", content: "", isStatic: true, enabled: true },
    { id: "example_dialogue", i18n: "block_example_dialogue", name: "Dialogue Examples", role: "system", content: "", isStatic: true, enabled: true },
    { id: "worldInfoAfter", i18n: "block_wi_after", name: "World Info After", role: "system", content: "", isStatic: true, enabled: true },
    { id: "chat_history", i18n: "block_chat_history", name: "Chat History", role: "system", content: "", isStatic: true, enabled: true },
    { id: "guided_generation", i18n: "block_guided_generation", name: "Guided Generation", role: "system", content: "[System Note: {{guidance}}]", isStatic: true, enabled: true }
];

const BLOCK_TO_ST_MAP = {
    'user_persona': 'personaDescription',
    'char_card': 'charDescription',
    'char_personality': 'charPersonality',
    'scenario': 'scenario',
    'chat_history': 'chatHistory',
    'example_dialogue': 'dialogueExamples',
    'worldInfoBefore': 'worldInfoBefore',
    'worldInfoAfter': 'worldInfoAfter',
    'guided_generation': 'guided_generation'
};

const ST_TO_BLOCK_MAP = Object.fromEntries(
    Object.entries(BLOCK_TO_ST_MAP).map(([k, v]) => [v, k])
);

export function convertSTPreset(data, fileName) {
    const orderedBlocks = [];
    const usedMandatory = new Set();
    const usedIdentifiers = new Set();

    let orderList = [];
    if (data.prompt_order && Array.isArray(data.prompt_order) && data.prompt_order.length > 0) {
        // Some presets have multiple orders, we take the one with most items or just the first one
        const bestOrder = data.prompt_order.reduce((prev, current) =>
            (current.order.length > prev.order.length) ? current : prev
            , data.prompt_order[0]);
        orderList = bestOrder.order;
    } else if (data.prompts) {
        orderList = data.prompts.map(p => ({ identifier: p.identifier, enabled: p.enabled !== false }));
    }

    const mapToMandatory = (identifier) => {
        return ST_TO_BLOCK_MAP[identifier] || null;
    };

    const processBlock = (item, isStashed = false) => {
        const p = data.prompts.find(p => p.identifier === item.identifier);
        if (!p) return;
        if (['enhanceDefinitions'].includes(item.identifier) && !p.content) return;

        usedIdentifiers.add(item.identifier);

        const isEnabled = isStashed ? false : (item.enabled !== undefined ? item.enabled : (p.enabled !== false));
        const mandatoryId = mapToMandatory(item.identifier);

        if (mandatoryId) {
            if (!usedMandatory.has(mandatoryId)) {
                const mb = mandatoryBlocks.find(b => b.id === mandatoryId);
                if (mb) {
                    orderedBlocks.push({ ...mb, enabled: isEnabled, isStashed: isStashed });
                    usedMandatory.add(mandatoryId);
                    return;
                }
            }
        }

        if (p.content !== undefined && p.content !== null) {
            let insertion_mode = 'relative';
            if (p.injection_position === 1) {
                insertion_mode = 'depth';
            }

            orderedBlocks.push({
                id: p.identifier || Date.now().toString(36) + Math.random().toString(36).substr(2),
                name: p.name || item.identifier,
                content: p.content,
                enabled: isEnabled,
                isStashed: isStashed,
                role: p.role || "system",
                insertion_mode: insertion_mode,
                depth: p.injection_depth !== undefined ? p.injection_depth : 4
            });
        }
    };

    // First pass: Process blocks from order list
    orderList.forEach((item) => processBlock(item));

    // Second pass: Process leftover blocks from data.prompts
    if (data.prompts) {
        data.prompts.forEach((p) => {
            if (!usedIdentifiers.has(p.identifier)) {
                processBlock({ identifier: p.identifier, enabled: false }, true); // Pass true for isStashed
            }
        });
    }

    // Add any remaining mandatory blocks that were never found
    mandatoryBlocks.forEach(mb => {
        if (!usedMandatory.has(mb.id)) {
            orderedBlocks.push({ ...mb });
        }
    });

    // Parse Regex Scripts from ST extensions
    const regexes = data.extensions?.regex_scripts ? data.extensions.regex_scripts.map(r => ({
        id: r.id || Date.now().toString(36) + Math.random().toString(36).substr(2),
        name: r.scriptName || 'Unnamed Regex',
        regex: r.findRegex || '',
        replacement: r.replaceString || '',
        trimOut: Array.isArray(r.trimStrings) ? r.trimStrings.join('\n') : (r.trimStrings || ''),
        placement: r.placement || [2],
        disabled: r.disabled !== undefined ? r.disabled : false,
        markdownOnly: r.markdownOnly || false,
        promptOnly: r.promptOnly || false,
        runOnEdit: r.runOnEdit || false,
        macroRules: (r.substituteRegex || 0).toString(),
        ephemerality: r.ephemerality || (r.markdownOnly === true && r.promptOnly === false ? [1] : r.markdownOnly === false && r.promptOnly === true ? [2] : [1, 2]),
        minDepth: r.minDepth || null,
        maxDepth: r.maxDepth || null
    })) : [];

    return {
        name: fileName || "Imported Preset",
        reasoningEnabled: data.reasoning_enabled || false,
        impersonationPrompt: data.impersonation_prompt || "",
        reasoningStart: data.reasoning_start || "",
        reasoningEnd: data.reasoning_end || "",
        mergePrompts: false,
        mergeRole: 'system',
        blocks: orderedBlocks,
        regexes: regexes
    };
}

export const LATEX_MACRO_DISABLE_MAP = {
    '{bot_persona}': ['char_personality', 'char_card'],
    '{user_persona}': ['user_persona'],
    '{scenario}': ['scenario'],
    '{example_dialogs}': ['example_dialogue'],
    '{lorebooks}': ['worldInfoBefore', 'worldInfoAfter'],
    '{summary}': ['summary', 'authors_note']
};

export function getLatexMacroDisabledBlockIds(content) {
    if (!content) return [];
    const ids = new Set();
    for (const [macro, blockIds] of Object.entries(LATEX_MACRO_DISABLE_MAP)) {
        if (content.includes(macro)) {
            blockIds.forEach(id => ids.add(id));
        }
    }
    return [...ids];
}

export function convertLatexPreset(data, fileName) {
    const orderedBlocks = [];
    const usedMandatory = new Set();
    const disabledNativeIds = new Set();

    const LATEX_TITLE_TO_BLOCK = {
        'persona': 'user_persona',
        'char description': 'char_card',
        'character card': 'char_card',
        'char personality': 'char_personality',
        'character personality': 'char_personality',
        'scenario': 'scenario',
        'world info before': 'worldInfoBefore',
        'world info after': 'worldInfoAfter',
        'chat history': 'chat_history',
        'dialogue examples': 'example_dialogue',
        'example dialogue': 'example_dialogue',
        'author\'s note': 'authors_note',
        'summary': 'summary',
        'guided generation': 'guided_generation'
    };

    const normalizeTitle = (title) => {
        const lower = (title || '').toLowerCase().replace(/[\u{2500}\u{2501}\u{1F6D1}\u{1F9E0}\u{1F9CD}\u{1F4C4}\u{1F3F3}\u{270F}\u{1F9D1}\u{1F527}]|\u{FE0F}|\u{200D}/gu, '').trim();
        for (const [key, blockId] of Object.entries(LATEX_TITLE_TO_BLOCK)) {
            if (lower.includes(key)) return blockId;
        }
        return null;
    };

    const tabs = data.tabs || [];

    const LATEX_TO_GLAZE_MACRO = {
        '{bot_persona}': '{{personality}}',
        '{user_persona}': '{{persona}}',
        '{scenario}': '{{scenario}}',
        '{example_dialogs}': '{{mesExamples}}',
        '{lorebooks}': '{{lorebooks}}',
        '{summary}': '{{summary}}'
    };

    const convertLatexMacrosToGlaze = (content) => {
        if (!content) return content;
        let result = content;
        for (const [latex, glaze] of Object.entries(LATEX_TO_GLAZE_MACRO)) {
            result = result.split(latex).join(glaze);
        }
        return result;
    };

    const allTabContent = tabs.map(t => t.content || '').join('\n');
    const macroReferencedBlockIds = getLatexMacroDisabledBlockIds(allTabContent);

    tabs.forEach((tab) => {
        const tabId = tab.id || generateId();
        const tabTitle = tab.title || '';
        const tabContent = convertLatexMacrosToGlaze(tab.content || '');
        const tabRole = tab.role || 'system';
        const tabEnabled = tab.enabled !== undefined ? tab.enabled : true;
        const tabDepth = tab.injectionDepth || 0;

        const mandatoryMatch = normalizeTitle(tabTitle);

        if (mandatoryMatch === 'chat_history') {
            usedMandatory.add('chat_history');
            const mb = mandatoryBlocks.find(b => b.id === 'chat_history');
            if (mb) orderedBlocks.push({ ...mb });
            return;
        }

        if (mandatoryMatch && !usedMandatory.has(mandatoryMatch)) {
            disabledNativeIds.add(mandatoryMatch);
            usedMandatory.add(mandatoryMatch);
        }

        let insertion_mode = 'relative';
        let depth = 4;
        if (tabDepth > 0) {
            insertion_mode = 'depth';
            depth = tabDepth;
        }

        orderedBlocks.push({
            id: tabId,
            name: tabTitle,
            content: tabContent,
            enabled: tabEnabled,
            isStashed: false,
            role: tabRole,
            insertion_mode,
            depth
        });
    });

    macroReferencedBlockIds.forEach(blockId => {
        if (blockId === 'chat_history') return;
        if (!usedMandatory.has(blockId)) {
            disabledNativeIds.add(blockId);
            usedMandatory.add(blockId);
        }
    });

    mandatoryBlocks.forEach(mb => {
        if (disabledNativeIds.has(mb.id)) {
            orderedBlocks.push({ ...mb, enabled: false, isStashed: false });
        } else if (!usedMandatory.has(mb.id)) {
            orderedBlocks.push({ ...mb });
        }
    });

    const EXTRA_DISABLED_BLOCKS = {
        'authors_note': { id: 'authors_note', name: "Author's Note", role: 'system', content: '', isStatic: true, i18n: 'magic_authors_notes', enabled: false, isStashed: false, insertion_mode: 'relative' },
        'summary': { id: 'summary', name: 'Summary', role: 'system', content: '', isStatic: true, i18n: 'magic_summary', enabled: false, isStashed: false, depth: 4, insertion_mode: 'relative', prefix: 'Summary: ' }
    };
    for (const [blockId, blockDef] of Object.entries(EXTRA_DISABLED_BLOCKS)) {
        if (disabledNativeIds.has(blockId)) {
            orderedBlocks.push({ ...blockDef });
        }
    }

    return {
        name: data.name || fileName || "Imported Preset",
        reasoningEnabled: false,
        impersonationPrompt: "",
        reasoningStart: "",
        reasoningEnd: "",
        mergePrompts: !!data.mergeConsecutiveRoles,
        mergeRole: 'system',
        blocks: orderedBlocks,
        regexes: [],
        disabledNativeIds: [...disabledNativeIds]
    };
}

export function exportSTPreset(preset) {
    const data = {
        name: preset.name || "Exported Preset",
        reasoning_enabled: preset.reasoningEnabled || false,
        impersonation_prompt: preset.impersonationPrompt || "",
        reasoning_start: preset.reasoningStart || "",
        reasoning_end: preset.reasoningEnd || "",
        prompts: [],
        prompt_order: [
            {
                character_id: 100000,
                order: [
                    { identifier: "main", enabled: true },
                    { identifier: "worldInfoBefore", enabled: true },
                    { identifier: "charDescription", enabled: true },
                    { identifier: "charPersonality", enabled: true },
                    { identifier: "scenario", enabled: true },
                    { identifier: "enhanceDefinitions", enabled: false },
                    { identifier: "nsfw", enabled: true },
                    { identifier: "worldInfoAfter", enabled: true },
                    { identifier: "dialogueExamples", enabled: true },
                    { identifier: "chatHistory", enabled: true },
                    { identifier: "jailbreak", enabled: true }
                ]
            },
            {
                character_id: 100001,
                order: []
            }
        ],
        extensions: {
            regex_scripts: []
        }
    };

    if (preset.blocks) {
        preset.blocks.forEach((b) => {
            const identifier = BLOCK_TO_ST_MAP[b.id] || b.id;

            const enabled = b.enabled !== undefined ? b.enabled : true;
            const isMarker = !!b.isStatic || !!ST_TO_BLOCK_MAP[identifier];
            const isSystem = isMarker || ["main", "nsfw", "jailbreak", "enhanceDefinitions"].includes(identifier);

            const promptObj = {
                id: identifier,
                identifier: identifier,
                name: b.name || identifier,
                system_prompt: isSystem,
                marker: isMarker,
                enabled: enabled
            };

            if (!isMarker) {
                promptObj.content = b.content || "";
                promptObj.role = b.role || "system";
                promptObj.injection_position = b.insertion_mode === 'depth' ? 1 : 0;
                promptObj.injection_depth = b.depth !== undefined ? b.depth : 4;
            }

            data.prompts.push(promptObj);

            if (!b.isStashed) {
                data.prompt_order[1].order.push({
                    identifier: identifier,
                    enabled: enabled
                });
            }
        });

        // Add worldInfoBefore and worldInfoAfter if missing, as ST expects them
        const orderIds = data.prompt_order[1].order.map(o => o.identifier);

        if (!orderIds.includes('worldInfoBefore')) {
            data.prompts.push({ identifier: "worldInfoBefore", name: "World Info (before)", system_prompt: true, marker: true, enabled: true });
            data.prompt_order[1].order.splice(1, 0, { identifier: "worldInfoBefore", enabled: true });
        }
        if (!orderIds.includes('worldInfoAfter')) {
            data.prompts.push({ identifier: "worldInfoAfter", name: "World Info (after)", system_prompt: true, marker: true, enabled: true });
            // Insert before chatHistory if possible, otherwise at the end
            const chatHistoryIndex = data.prompt_order[1].order.findIndex(o => o.identifier === 'chatHistory');
            const insertIdx = chatHistoryIndex !== -1 ? chatHistoryIndex : data.prompt_order[1].order.length;
            data.prompt_order[1].order.splice(insertIdx, 0, { identifier: "worldInfoAfter", enabled: true });
        }
    }

    if (preset.regexes) {
        data.extensions.regex_scripts = preset.regexes.map(r => ({
            id: r.id,
            scriptName: r.name || "Unnamed Regex",
            findRegex: r.regex || "",
            replaceString: r.replacement || "",
            trimStrings: r.trimOut ? r.trimOut.split('\n') : [],
            placement: r.placement || [2],
            disabled: r.disabled !== undefined ? r.disabled : false,
            markdownOnly: r.ephemerality ? r.ephemerality.includes(1) && !r.ephemerality.includes(2) : (r.markdownOnly !== undefined ? r.markdownOnly : false),
            promptOnly: r.ephemerality ? r.ephemerality.includes(2) && !r.ephemerality.includes(1) : (r.promptOnly !== undefined ? r.promptOnly : false),
            runOnEdit: r.runOnEdit !== undefined ? r.runOnEdit : false,
            substituteRegex: r.macroRules ? parseInt(r.macroRules) || 0 : 0,
            ephemerality: r.ephemerality || [1, 2],
            minDepth: r.minDepth || null,
            maxDepth: r.maxDepth || null
        }));
    }

    return data;
}

import JSZip from 'jszip';
import { parseCharacterCard } from '@/utils/characterIO.js';
import { importSillyTavernChat } from '@/core/services/chatImporter.js';
import { convertSTPreset } from '@/core/services/presetImportService.js';
import { importSTLorebook, initLorebookState, saveLorebooks } from '@/core/states/lorebookState.js';
import { db } from '@/utils/db.js';

/**
 * Imports a SillyTavern backup ZIP file.
 * Merges characters, lorebooks, presets, chats, and personas into the current DB.
 * @param {File|Blob} zipFile
 * @param {Function} [onProgress] - Called with a status string at each phase.
 * @returns {Promise<{characters: number, lorebooks: number, presets: number, chats: number, personas: number, errors: string[]}>}
 */
export async function importSTBackupFromZip(zipFile, onProgress) {
    const progress = (msg) => { if (onProgress) onProgress(msg); };
    const result = { characters: 0, lorebooks: 0, presets: 0, chats: 0, personas: 0, errors: [] };

    const zip = await JSZip.loadAsync(zipFile);

    // ── Clear existing DB before import ─────────────────────────────────────
    progress('clearing');
    const database = await db.open();
    await new Promise((res, rej) => {
        const tx = database.transaction(['characters', 'personas', 'keyvalue'], 'readwrite');
        tx.objectStore('characters').clear();
        tx.objectStore('personas').clear();
        // Clear all keys from keyvalue (lorebooks, api presets, chats)
        tx.objectStore('keyvalue').clear();

        tx.oncomplete = res;
        tx.onerror = () => rej(tx.error);
    });
    database.close();
    // Clear presets and regexes from localStorage
    localStorage.removeItem('silly_cradle_presets');
    localStorage.removeItem('regex_scripts');

    // charFolderName (no extension) → characterId, populated during character import
    const charNameToId = {};

    // ── Phase 1: Characters ─────────────────────────────────────────────────
    progress('characters');
    const charPaths = Object.keys(zip.files).filter(p => {
        if (!p.startsWith('characters/') || zip.files[p].dir) return false;
        const parts = p.split('/');
        return parts.length === 2 && parts[1].toLowerCase().endsWith('.png');
    });

    for (const path of charPaths) {
        try {
            const buf = await zip.files[path].async('arraybuffer');
            const filename = path.split('/').pop();
            const file = new File([buf], filename, { type: 'image/png' });
            const charData = await parseCharacterCard(file);
            if (!charData.id) {
                charData.id = Date.now().toString(36) + Math.random().toString(36).substr(2);
            }
            await db.saveCharacter(charData);
            charNameToId[filename.replace(/\.png$/i, '')] = charData.id;
            result.characters++;
        } catch (err) {
            result.errors.push(`Character ${path}: ${err.message}`);
        }
    }

    // ── Phase 2: Lorebooks ───────────────────────────────────────────────────
    progress('lorebooks');
    await initLorebookState();
    const lorebookPaths = Object.keys(zip.files).filter(p =>
        p.startsWith('worlds/') && !zip.files[p].dir && p.toLowerCase().endsWith('.json')
    );

    for (const path of lorebookPaths) {
        try {
            const text = await zip.files[path].async('string');
            const json = JSON.parse(text);
            const fileName = path.split('/').pop();
            await importSTLorebook(json, fileName);
            result.lorebooks++;
        } catch (err) {
            result.errors.push(`Lorebook ${path}: ${err.message}`);
        }
    }
    if (result.lorebooks > 0) await saveLorebooks();

    // ── Phase 3: Presets ─────────────────────────────────────────────────────
    progress('presets');
    const presetPaths = Object.keys(zip.files).filter(p =>
        p.startsWith('OpenAI Settings/') && !zip.files[p].dir && p.toLowerCase().endsWith('.json')
    );

    if (presetPaths.length > 0) {
        const existingPresetsRaw = localStorage.getItem('silly_cradle_presets');
        const existingPresets = existingPresetsRaw ? JSON.parse(existingPresetsRaw) : {};

        for (const path of presetPaths) {
            try {
                const text = await zip.files[path].async('string');
                const json = JSON.parse(text);
                const fileName = path.split('/').pop().replace(/\.json$/i, '');
                const preset = convertSTPreset(json, fileName);
                const id = Date.now().toString(36) + Math.random().toString(36).substr(2);
                preset.id = id;
                existingPresets[id] = preset;
                result.presets++;
            } catch (err) {
                result.errors.push(`Preset ${path}: ${err.message}`);
            }
        }
        localStorage.setItem('silly_cradle_presets', JSON.stringify(existingPresets));
    }

    // ── Phase 4: Chats ───────────────────────────────────────────────────────
    progress('chats');
    const chatPaths = Object.keys(zip.files).filter(p => {
        if (!p.startsWith('chats/') || zip.files[p].dir) return false;
        const ext = p.toLowerCase();
        return ext.endsWith('.jsonl') || ext.endsWith('.json');
    });

    for (const path of chatPaths) {
        try {
            const parts = path.split('/');
            if (parts.length < 3) continue; // must be chats/<folder>/<file>
            const charFolderName = parts[1];
            const characterId = charNameToId[charFolderName];
            if (!characterId) {
                result.errors.push(`Chat ${path}: no imported character matched folder "${charFolderName}"`);
                continue;
            }
            const text = await zip.files[path].async('string');
            const blob = new Blob([text], { type: 'text/plain' });
            await importSillyTavernChat(blob, characterId, null);
            result.chats++;
        } catch (err) {
            result.errors.push(`Chat ${path}: ${err.message}`);
        }
    }

    // ── Phase 5: Personas ────────────────────────────────────────────────────
    progress('personas');

    // settings.json might be in the root or inside a folder if the user zipped the entire ST folder.
    const settingsPath = Object.keys(zip.files).find(p => p.toLowerCase().endsWith('settings.json') && !zip.files[p].dir);

    if (settingsPath) {
        try {
            const text = await zip.files[settingsPath].async('string');
            const settings = JSON.parse(text);

            // ST stores personas under power_user, not at root level
            const pu = settings.power_user || settings;
            const personasMap = pu.personas || settings.personas || {};
            const descriptionsMap = pu.persona_descriptions || settings.persona_descriptions || {};

            for (const [avatarFilename, personaName] of Object.entries(personasMap)) {
                if (!avatarFilename) continue;

                const descData = descriptionsMap[avatarFilename] || {};

                // Try to load the avatar image from User Avatars/ folder
                let avatarData = null;
                const avatarPath = Object.keys(zip.files).find(p =>
                    p.toLowerCase().endsWith(avatarFilename.toLowerCase()) &&
                    p.toLowerCase().includes('user avatars')
                );
                if (avatarPath) {
                    try {
                        const buf = await zip.files[avatarPath].async('arraybuffer');
                        const bytes = new Uint8Array(buf);
                        let binary = '';
                        for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
                        avatarData = 'data:image/png;base64,' + btoa(binary);
                    } catch (_) { /* avatar not critical */ }
                }

                const persona = {
                    id: Date.now().toString(36) + Math.random().toString(36).substr(2),
                    name: personaName,
                    avatar: avatarData,
                    prompt: descData.description || '',
                };

                await db.savePersona(persona);
                result.personas++;
            }
        } catch (err) {
            result.errors.push(`Personas (settings.json): ${err.message}`);
        }
    }

    return result;
}

import { db, getSyncDeletedEntries, clearSyncDeletedEntry } from '@/utils/db.js';
import { encryptForSync, decryptFromSync, hasSyncKey, getSyncKey } from '@/core/services/crypto/keyManager.js';
import { isSyncIncludingApiKeys } from '@/core/config/ProviderProfiles.js';

const CLOUD_BASE = '/Glaze';

const ENTITY_TYPES = {
    CHARACTER: 'character',
    PERSONA: 'persona',
    CHAT: 'chat',
    LOREBOOKS: 'lorebooks',
    API_PRESETS: 'api_presets',
    THEME_PRESETS: 'theme_presets',
    THEME_STATE: 'theme_state',
    LOCAL_STORAGE: 'local_storage',
    MANIFEST: 'manifest'
};

let _encryptionEnabled = false;

export function isEncryptionEnabled() {
    return _encryptionEnabled;
}

export async function detectEncryptionState() {
    _encryptionEnabled = await hasSyncKey();
    return _encryptionEnabled;
}

function ext() {
    return _encryptionEnabled ? '.enc' : '.json';
}

function cloudPath(type, id) {
    const e = ext();
    switch (type) {
        case ENTITY_TYPES.CHARACTER: return `${CLOUD_BASE}/characters/${id}${e}`;
        case ENTITY_TYPES.PERSONA: return `${CLOUD_BASE}/personas/${id}${e}`;
        case ENTITY_TYPES.CHAT: return `${CLOUD_BASE}/chats/${id}${e}`;
        case ENTITY_TYPES.LOREBOOKS: return `${CLOUD_BASE}/lorebooks${e}`;
        case ENTITY_TYPES.API_PRESETS: return `${CLOUD_BASE}/api_presets${e}`;
        case ENTITY_TYPES.THEME_PRESETS: return `${CLOUD_BASE}/theme_presets${e}`;
        case ENTITY_TYPES.THEME_STATE: return `${CLOUD_BASE}/theme_state${e}`;
        case ENTITY_TYPES.LOCAL_STORAGE: return `${CLOUD_BASE}/local_storage${e}`;
        case ENTITY_TYPES.MANIFEST: return `${CLOUD_BASE}/manifest.json`;
        default: return `${CLOUD_BASE}/misc/${id}${e}`;
    }
}

function generateDeviceId() {
    const stored = localStorage.getItem('gz_sync_device_id');
    if (stored) return stored;
    const id = Date.now().toString(36) + Math.random().toString(36).substr(2, 8);
    localStorage.setItem('gz_sync_device_id', id);
    return id;
}

function getDeviceId() {
    return localStorage.getItem('gz_sync_device_id') || generateDeviceId();
}

async function encryptEntity(data, key) {
    if (!key) return data;
    return encryptForSync(data, key);
}

async function decryptEntity(encrypted, key) {
    if (!key) return encrypted;
    if (!encrypted.iv || !encrypted.data) return encrypted;
    return decryptFromSync(encrypted, key);
}

const MANIFEST_VERSION = 2;

function entryKey(type, id) {
    return `${type}:${id}`;
}

function clone(obj) {
    return JSON.parse(JSON.stringify(obj));
}

async function getCloudVerificationCandidate(adapter) {
    const cloudFiles = await listAllFiles(adapter);
    const candidate = cloudFiles.find(file => {
        const path = file.path_display || file.path || '';
        return path !== cloudPath(ENTITY_TYPES.MANIFEST);
    });

    if (!candidate) {
        return null;
    }

    return adapter.download(candidate.path_display || candidate.path);
}

export async function cloudHasData(adapter) {
    try {
        const result = await adapter.download(cloudPath(ENTITY_TYPES.MANIFEST));
        return result !== null;
    } catch {
        return false;
    }
}

export async function verifyCloudKey(adapter, key) {
    const candidate = await getCloudVerificationCandidate(adapter);
    if (!candidate) return true;

    const parsed = JSON.parse(candidate.data);
    if (!_encryptionEnabled) return true;
    if (!parsed.iv || !parsed.data) return true;

    await decryptEntity(parsed, key);
    return true;
}

export async function buildManifest(lastSync, deviceId) {
    return {
        version: MANIFEST_VERSION,
        deviceId: deviceId || getDeviceId(),
        lastSync: lastSync || 0,
        createdAt: Date.now(),
        entries: {}
    };
}

async function computeSyncHash(data) {
    const normalized = JSON.stringify(data ?? null);
    const bytes = new TextEncoder().encode(normalized);
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function readCloudManifestV2(adapter) {
    const manifest = await readManifest(adapter);
    if (manifest?.version === MANIFEST_VERSION && manifest?.entries) {
        return manifest;
    }
    return null;
}

async function readLocalManifestV2() {
    return (await db.get('gz_sync_manifest_v2')) || null;
}

async function writeLocalManifestV2(manifest) {
    await db.set('gz_sync_manifest_v2', manifest);
}

async function collectSingletonEntries() {
    const singletons = [
        { type: ENTITY_TYPES.LOREBOOKS, id: 'lorebooks', data: await db.get('gz_lorebooks') },
        { type: ENTITY_TYPES.API_PRESETS, id: 'api_presets', data: await db.get('gz_api_connection_presets') },
        { type: ENTITY_TYPES.THEME_PRESETS, id: 'theme_presets', data: await db.get('gz_theme_presets') },
        { type: ENTITY_TYPES.THEME_STATE, id: 'theme_state', data: await db.get('gz_theme_active_preset') }
    ];

    const lsData = {};
    const lsKeys = [
        'silly_cradle_presets', 'silly_cradle_current_preset_id', 'gz_preset_connections',
        'regex_scripts', 'gz_active_persona_id', 'gz_persona_connections',
        'gz_lang', 'gz_theme', 'gz_chat_padding_lr', 'gz_force_mobile_layout',
        'gz_battery_saver_ui',
        // Legacy LLM runtime
        'api-endpoint', 'api-max-tokens', 'api-context',
        'gz_api_provider', 'gz_api_endpoint_normalized',
        'gz_api_temp', 'gz_api_topp', 'gz_api_stream',
        'gz_api_auto_hide_images', 'gz_api_auto_hide_images_n',
        'gz_api_request_reasoning', 'gz_api_reasoning_start', 'gz_api_reasoning_end', 'gz_api_reasoning_effort',
        'gz_api_connect_timeout', 'gz_api_stream_timeout',
        // Embeddings (non-sensitive)
        'gz_embedding_use_same', 'gz_embedding_target', 'gz_embedding_scan_depth',
        'gz_embedding_threshold', 'gz_embedding_top_k', 'gz_embedding_max_chunk_tokens',
        'gz_embedding_enabled',
        // Image Gen (non-sensitive)
        'gz_imggen_enabled', 'gz_imggen_api_type', 'gz_imggen_endpoint', 'gz_imggen_model',
        'gz_imggen_size', 'gz_imggen_quality', 'gz_imggen_aspect_ratio', 'gz_imggen_image_size',
        'gz_imggen_naistera_model', 'gz_imggen_naistera_aspect_ratio',
        'gz_imggen_naistera_send_char_avatar', 'gz_imggen_naistera_send_user_avatar',
        'gz_imggen_image_context_enabled', 'gz_imggen_image_context_count',
        'gz_imggen_additional_refs',
        // Provider profiles (metadata only; the JSON with keys is conditional below)
        'gz_active_llm_profile_id', 'gz_service_profile_map', 'gz_provider_profiles_migrated',
        'gz_sync_include_api_keys'
    ];
    const includeKeys = isSyncIncludingApiKeys();
    if (includeKeys) {
        lsKeys.push('api-key', 'api-model', 'gz_embedding_key', 'gz_embedding_model', 'gz_embedding_endpoint');
        lsKeys.push('gz_provider_profiles', 'gz_imggen_api_key');
    }
    for (const k of lsKeys) {
        const v = localStorage.getItem(k);
        if (v !== null) lsData[k] = v;
    }
    singletons.push({ type: ENTITY_TYPES.LOCAL_STORAGE, id: 'local_storage', data: Object.keys(lsData).length > 0 ? lsData : null });
    return singletons;
}

async function buildLocalManifestV2() {
    const manifest = await buildManifest(Date.now(), getDeviceId());
    const previousManifest = await readLocalManifestV2();
    const previousEntries = previousManifest?.entries || {};
    manifest.entries = {};

    const characters = await db.getAll('characters');
    for (const char of characters) {
        if (!char?.id) continue;
        const hash = await computeSyncHash(char);
        const previousEntry = previousEntries[entryKey(ENTITY_TYPES.CHARACTER, char.id)];
        manifest.entries[entryKey(ENTITY_TYPES.CHARACTER, char.id)] = {
            type: ENTITY_TYPES.CHARACTER,
            id: char.id,
            path: cloudPath(ENTITY_TYPES.CHARACTER, char.id),
            updatedAt: char.updatedAt || previousEntry?.updatedAt || Date.now(),
            hash,
            deleted: false
        };
    }

    const personas = await db.getAll('personas');
    for (const persona of personas) {
        if (!persona?.id) continue;
        const hash = await computeSyncHash(persona);
        const previousEntry = previousEntries[entryKey(ENTITY_TYPES.PERSONA, persona.id)];
        manifest.entries[entryKey(ENTITY_TYPES.PERSONA, persona.id)] = {
            type: ENTITY_TYPES.PERSONA,
            id: persona.id,
            path: cloudPath(ENTITY_TYPES.PERSONA, persona.id),
            updatedAt: persona.updatedAt || previousEntry?.updatedAt || Date.now(),
            hash,
            deleted: false
        };
    }

    const chats = await db.getChats();
    for (const [charId, chatData] of Object.entries(chats || {})) {
        const hash = await computeSyncHash(chatData);
        const previousEntry = previousEntries[entryKey(ENTITY_TYPES.CHAT, charId)];
        manifest.entries[entryKey(ENTITY_TYPES.CHAT, charId)] = {
            type: ENTITY_TYPES.CHAT,
            id: charId,
            path: cloudPath(ENTITY_TYPES.CHAT, charId),
            updatedAt: chatData?.updatedAt || previousEntry?.updatedAt || Date.now(),
            hash,
            deleted: false
        };
    }

    const singletons = await collectSingletonEntries();
    for (const item of singletons) {
        if (item.data === null || item.data === undefined) continue;
        const manifestKey = entryKey(item.type, item.id);
        const hash = await computeSyncHash(item.data);
        const previousEntry = previousEntries[manifestKey];
        manifest.entries[entryKey(item.type, item.id)] = {
            type: item.type,
            id: item.id,
            path: cloudPath(item.type, item.id),
            updatedAt: previousEntry?.hash === hash && !previousEntry?.deleted
                ? previousEntry.updatedAt
                : Date.now(),
            hash,
            deleted: false
        };
    }

    const deletions = await getSyncDeletedEntries();
    for (const [key, deletion] of Object.entries(deletions)) {
        manifest.entries[key] = {
            type: deletion.type,
            id: deletion.id,
            path: cloudPath(deletion.type, deletion.id),
            updatedAt: deletion.updatedAt,
            hash: null,
            deleted: true
        };
    }

    manifest.lastSync = Date.now();
    return manifest;
}

async function readCloudEntityByEntry(adapter, entry, key) {
    let result = await adapter.download(entry.path);
    if (!result) {
        const altPath = entry.path.endsWith('.enc')
            ? entry.path.replace('.enc', '.json')
            : entry.path.replace('.json', '.enc');
        result = await adapter.download(altPath);
    }
    if (!result) return null;
    const parsed = JSON.parse(result.data);
    return decryptEntity(parsed, key);
}

async function applyCloudEntry(adapter, entry, key) {
    if (entry.deleted) {
        if (entry.type === ENTITY_TYPES.CHARACTER) {
            await db.delete('characters', entry.id);
        } else if (entry.type === ENTITY_TYPES.PERSONA) {
            await db.delete('personas', entry.id);
        } else if (entry.type === ENTITY_TYPES.CHAT) {
            await db.delete('keyvalue', `gz_chat_${entry.id}`);
        }
        await clearSyncDeletedEntry(entry.type, entry.id);
        return null;
    }

    const entity = await readCloudEntityByEntry(adapter, entry, key);
    if (entry.type === ENTITY_TYPES.CHARACTER) {
        await db.put('characters', entity);
        await clearSyncDeletedEntry(entry.type, entry.id);
    } else if (entry.type === ENTITY_TYPES.PERSONA) {
        await db.put('personas', entity);
        await clearSyncDeletedEntry(entry.type, entry.id);
    } else if (entry.type === ENTITY_TYPES.CHAT) {
        await db.set(`gz_chat_${entry.id}`, entity);
        await clearSyncDeletedEntry(entry.type, entry.id);
    } else if (entry.type === ENTITY_TYPES.LOREBOOKS) {
        await db.queuedSet('gz_lorebooks', entity);
    } else if (entry.type === ENTITY_TYPES.API_PRESETS) {
        await db.queuedSet('gz_api_connection_presets', entity);
    } else if (entry.type === ENTITY_TYPES.THEME_PRESETS) {
        await db.queuedSet('gz_theme_presets', entity);
    } else if (entry.type === ENTITY_TYPES.THEME_STATE) {
        await db.queuedSet('gz_theme_active_preset', entity);
    } else if (entry.type === ENTITY_TYPES.LOCAL_STORAGE) {
        for (const [lsKey, lsVal] of Object.entries(entity || {})) {
            localStorage.setItem(lsKey, lsVal);
        }
    }
    return entity;
}

function getBreakdownBucket(type) {
    if (type === ENTITY_TYPES.CHARACTER) return 'characters';
    if (type === ENTITY_TYPES.PERSONA) return 'personas';
    if (type === ENTITY_TYPES.CHAT) return 'chats';
    return 'settings';
}

function needsConflict(localEntry, cloudEntry) {
    return !!localEntry && !localEntry.deleted && localEntry.updatedAt > cloudEntry.updatedAt;
}

async function getLocalConflictEntity(type, id) {
    if (type === ENTITY_TYPES.CHARACTER) return getLocalCharacter(id);
    if (type === ENTITY_TYPES.PERSONA) return getLocalPersona(id);
    if (type === ENTITY_TYPES.CHAT) return getLocalChat(id);
    return null;
}

function getConflictName(type, localEntity, cloudEntity, id) {
    if (type === ENTITY_TYPES.CHARACTER || type === ENTITY_TYPES.PERSONA) {
        return localEntity?.name || cloudEntity?.name || id;
    }
    if (type === ENTITY_TYPES.CHAT) {
        return getChatName(localEntity, cloudEntity, id);
    }
    return id;
}

async function deleteCloudFileIfExists(adapter, entry) {
    try {
        await adapter.deleteFile(entry.path);
    } catch {
        // Ignore missing payload deletes; manifest remains source of truth.
    }
}

async function pushManifestV2(adapter, key, onProgress) {
    const cloudManifest = await readCloudManifestV2(adapter);
    const localManifest = await buildLocalManifestV2();
    const cloudEntries = cloudManifest?.entries || {};
    const breakdown = { characters: 0, personas: 0, chats: 0, settings: 0 };
    let pushed = 0;
    let skipped = 0;

    const allKeys = new Set([...Object.keys(localManifest.entries), ...Object.keys(cloudEntries)]);
    const allEntries = Array.from(allKeys);

    for (let i = 0; i < allEntries.length; i++) {
        const keyName = allEntries[i];
        const localEntry = localManifest.entries[keyName];
        const cloudEntry = cloudEntries[keyName];
        const phase = getBreakdownBucket((localEntry || cloudEntry)?.type);

        if (!localEntry) {
            if (onProgress) onProgress(phase, i + 1, allEntries.length);
            continue;
        }

        const shouldUpload = !cloudEntry
            || localEntry.deleted !== cloudEntry.deleted
            || localEntry.updatedAt > cloudEntry.updatedAt
            || localEntry.hash !== cloudEntry.hash;

        if (!shouldUpload) {
            skipped++;
            if (onProgress) onProgress(phase, i + 1, allEntries.length);
            continue;
        }

        if (localEntry.deleted) {
            await deleteCloudFileIfExists(adapter, localEntry);
        } else {
            let payload = null;
            if (localEntry.type === ENTITY_TYPES.CHARACTER) payload = await getLocalCharacter(localEntry.id);
            else if (localEntry.type === ENTITY_TYPES.PERSONA) payload = await getLocalPersona(localEntry.id);
            else if (localEntry.type === ENTITY_TYPES.CHAT) payload = await getLocalChat(localEntry.id);
            else {
                const singletons = await collectSingletonEntries();
                payload = singletons.find(item => item.type === localEntry.type && item.id === localEntry.id)?.data ?? null;
            }

            if (payload !== null && payload !== undefined) {
                const encrypted = await encryptEntity(payload, key);
                await adapter.upload(localEntry.path, JSON.stringify(encrypted));
            }
        }

        pushed++;
        breakdown[phase]++;
        if (onProgress) onProgress(phase, i + 1, allEntries.length);
    }

    localManifest.lastSync = Date.now();
    localManifest.createdAt = cloudManifest?.createdAt || Date.now();
    await adapter.upload(cloudPath(ENTITY_TYPES.MANIFEST), JSON.stringify(localManifest));
    await writeLocalManifestV2(localManifest);

    return { pushed, skipped, total: pushed + skipped, breakdown };
}

async function pullManifestV2(adapter, key, onProgress, onConflict) {
    const cloudManifest = await readCloudManifestV2(adapter);
    if (!cloudManifest) {
        throw new Error('Cloud manifest v2 not found');
    }

    const localManifest = await buildLocalManifestV2();
    const cloudEntries = cloudManifest.entries || {};
    const localEntries = localManifest.entries || {};
    const allKeys = new Set([...Object.keys(cloudEntries), ...Object.keys(localEntries)]);
    const allEntries = Array.from(allKeys);
    const breakdown = { characters: 0, personas: 0, chats: 0, settings: 0 };
    const decryptErrors = [];
    const conflicts = [];
    let pulled = 0;

    for (let i = 0; i < allEntries.length; i++) {
        const keyName = allEntries[i];
        const cloudEntry = cloudEntries[keyName];
        const localEntry = localEntries[keyName];
        const phase = getBreakdownBucket((cloudEntry || localEntry)?.type);

        if (!cloudEntry) {
            if (onProgress) onProgress(phase, i + 1, allEntries.length);
            continue;
        }

        const cloudIsNewer = !localEntry || cloudEntry.updatedAt > localEntry.updatedAt || cloudEntry.hash !== localEntry.hash || cloudEntry.deleted !== localEntry.deleted;
        if (!cloudIsNewer) {
            if (onProgress) onProgress(phase, i + 1, allEntries.length);
            continue;
        }

        if (needsConflict(localEntry, cloudEntry)) {
            const localEntity = await getLocalConflictEntity(cloudEntry.type, cloudEntry.id);
            let cloudEntity = null;
            if (!cloudEntry.deleted) {
                try {
                    cloudEntity = await readCloudEntityByEntry(adapter, cloudEntry, key);
                } catch (e) {
                    decryptErrors.push({ type: cloudEntry.type, id: cloudEntry.id, error: e.message });
                    if (onProgress) onProgress(phase, i + 1, allEntries.length);
                    continue;
                }
            }
            const conflict = {
                type: cloudEntry.type,
                id: cloudEntry.id,
                name: getConflictName(cloudEntry.type, localEntity, cloudEntity, cloudEntry.id),
                local: localEntity,
                cloud: cloudEntity,
                cloudModified: cloudEntry.updatedAt
            };
            conflicts.push(conflict);
            if (onConflict) onConflict(conflict);
            if (onProgress) onProgress(phase, i + 1, allEntries.length);
            continue;
        }

        try {
            await applyCloudEntry(adapter, cloudEntry, key);
            pulled++;
            breakdown[phase]++;
        } catch (e) {
            decryptErrors.push({ type: cloudEntry.type, id: cloudEntry.id, error: e.message });
        }

        if (onProgress) onProgress(phase, i + 1, allEntries.length);
    }

    await writeLocalManifestV2(clone(cloudManifest));

    if (pulled === 0 && conflicts.length === 0 && decryptErrors.length > 0 && Object.keys(cloudEntries).length > 0) {
        if (_encryptionEnabled) {
            throw new Error('Cloud data was found, but none of it could be decrypted. Restore the correct recovery phrase and try again.');
        } else {
            throw new Error('Cloud data was found, but could not be read. Check sync settings and try again.');
        }
    }

    return { pulled, conflicts, decryptErrors, breakdown };
}

export async function pushEntities(adapter, key, onProgress) {
    return pushManifestV2(adapter, key, onProgress);
}

export async function pullEntities(adapter, key, onProgress, onConflict) {
    if (!key && _encryptionEnabled) throw new Error('Encryption key not available. Set up encryption first.');
    return pullManifestV2(adapter, key, onProgress, onConflict);
}

async function readManifest(adapter) {
    try {
        const result = await adapter.download(cloudPath(ENTITY_TYPES.MANIFEST));
        if (result) {
            return JSON.parse(result.data);
        }
    } catch {}
    return null;
}

async function listAllFiles(adapter) {
    const files = [];
    try {
        let result = await adapter.listFolder(CLOUD_BASE);
        if (!result || !result.entries) return files;

        for (const entry of result.entries) {
            if (entry['.tag'] === 'folder') {
                const subResult = await adapter.listFolder(entry.path_display || entry.path_lower);
                if (subResult && subResult.entries) {
                    files.push(...subResult.entries.filter(e => e['.tag'] === 'file'));
                }
            } else if (entry['.tag'] === 'file') {
                files.push(entry);
            }
        }

        while (result && result.has_more && result.cursor) {
            result = await adapter.listFolderContinue(result.cursor);
            if (result && result.entries) {
                for (const entry of result.entries) {
                    if (entry['.tag'] === 'folder') {
                        const subResult = await adapter.listFolder(entry.path_display || entry.path_lower);
