export async function vectorSearchLorebooks(history = [], currentText = '', char = null, chatId = null) {
    // Check global search type setting - skip if keys-only
    if (lorebookState.globalSettings.searchType === 'keys') {
        console.info('[vectorSearchLorebooks] skipped: keys-only search mode');
        return [];
    }

    const config = getEmbeddingConfig();
    if (!isEmbeddingConfigured()) {
        console.info('[vectorSearchLorebooks] skipped: embedding config incomplete');
        return [];
    }

    const charId = char?.id;

    const activeLorebooks = lorebookState.lorebooks.filter(lb => {
        if (lb.enabled) return true;
        if (charId && lorebookState.activations?.character?.[charId]?.includes(lb.id)) return true;
        if (chatId && lorebookState.activations?.chat?.[chatId]?.includes(lb.id)) return true;
        return false;
    });

    if (activeLorebooks.length === 0) {
        console.info('[vectorSearchLorebooks] skipped: no active lorebooks for context', {
            charId,
            chatId,
            totalLorebooks: lorebookState.lorebooks.length
        });
        return [];
    }

    const vectorEntries = [];
    activeLorebooks.forEach(lb => {
        lb.entries.forEach(entry => {
            if (entry.enabled !== false && entry.vectorSearch) {
                if (char && entry.characterFilter) {
                    const { isExclude, names } = entry.characterFilter;
                    if (names && names.length > 0) {
                        const charName = (char.name || "").toLowerCase();
                        const isInCategory = names.some(n => charName.includes(n.toLowerCase()));
                        if (isExclude && isInCategory) return;
                        if (!isExclude && !isInCategory) return;
                    }
                }
                vectorEntries.push({ ...entry, lorebookName: lb.name, lorebookId: lb.id });
            }
        });
    });

    if (vectorEntries.length === 0) {
        console.info('[vectorSearchLorebooks] skipped: no vector-enabled entries', {
            activeLorebooks: activeLorebooks.length
        });
        return [];
    }

    const allEmbeddings = await db.getEmbeddingsBySource('lorebook_entry');
    const embeddingMap = new Map(allEmbeddings.map(e => [e.id, e]));

    const candidates = [];
    const missingEmbeddings = [];
    for (const entry of vectorEntries) {
        const emb = embeddingMap.get(entry.id);
        // NEW: Support both multi-vector (vectors) and legacy (vector)
        if (emb && (emb.vectors || emb.vector)) {
            const candidate = { ...entry, retrievalHints: emb.retrievalHints || [] };
            if (emb.vectors) {
                candidate.vectors = emb.vectors;  // Multi-vector
            } else if (emb.vector) {
                candidate.vector = emb.vector;  // Legacy single vector
            }
            candidates.push(candidate);
        } else {
            missingEmbeddings.push({
                id: entry.id,
                comment: entry.comment,
                hasEmb: !!emb,
                hasVectors: emb?.vectors ? true : false,
                hasVector: emb?.vector ? true : false
            });
        }
    }
    
    if (missingEmbeddings.length > 0) {
        console.warn('[vectorSearchLorebooks] entries missing embeddings', {
            count: missingEmbeddings.length,
            entries: missingEmbeddings
        });
    }

    if (candidates.length === 0) {
        console.info('[vectorSearchLorebooks] skipped: no indexed vector candidates', {
            vectorEntries: vectorEntries.length,
            storedEmbeddings: allEmbeddings.length
        });
        return [];
    }

    const scanDepth = config.scanDepth || 5;
    const recentHistory = history.slice(-scanDepth);
    const recentUserParts = recentHistory
        .filter(m => m.role === 'user')
        .map(m => m.content)
        .filter(Boolean);
    const currentTextTrimmed = currentText && currentText.trim() ? currentText.trim() : '';
    const focusedQueryParts = recentUserParts.length > 0 ? [...recentUserParts] : [];
    if (currentTextTrimmed) {
        focusedQueryParts.push(currentTextTrimmed);
    }
    const fallbackQueryParts = recentHistory.map(m => m.content).filter(Boolean);
    if (currentTextTrimmed) {
        fallbackQueryParts.push(currentTextTrimmed);
    }

    const focusedQueryText = focusedQueryParts.join('\n');
    const fallbackQueryText = fallbackQueryParts.join('\n');
    const queryText = (focusedQueryParts.length > 0 ? focusedQueryParts : fallbackQueryParts).join('\n');
    if (!queryText.trim()) {
        console.info('[vectorSearchLorebooks] skipped: empty query text', {
            historyMessages: history.length,
            hasCurrentText: !!(currentText && currentText.trim())
        });
        return [];
    }

    const globalSettings = lorebookState.globalSettings;
    const effectiveThreshold = globalSettings.vectorThreshold || 0.45;
    const effectiveTopK = globalSettings.vectorTopK || 10;

    console.info('[vectorSearchLorebooks] querying embeddings', {
        charId,
        chatId,
        activeLorebooks: activeLorebooks.length,
        vectorEntries: vectorEntries.length,
        indexedCandidates: candidates.length,
        historyMessages: history.length,
        userMessagesUsed: recentUserParts.length,
        focusedQueryLength: focusedQueryText.length,
        fallbackQueryLength: fallbackQueryText.length,
        hasCurrentText: !!(currentText && currentText.trim()),
        queryLength: queryText.length,
        threshold: effectiveThreshold,
        topK: effectiveTopK,
        usingGlobalSettings: true
    });

    try {
        const hybridQueryText = focusedQueryText || fallbackQueryText;

        function stripOOC(text) {
            return text.replace(/\[OOC:\s*/gi, '').replace(/\(OOC:\s*/gi, '').replace(/\s*\]\s*/g, ' ').replace(/\s*\)\s*/g, ' ').trim();
        }

        const runSearch = async (text, label) => {
            if (!text || !text.trim()) return [];
            const cleanText = stripOOC(text);
            console.info('[vectorSearchLorebooks] embedding query', {
                label,
                queryLength: cleanText.length,
                queryPreview: cleanText.substring(0, 200),
                originalPreview: text.substring(0, 200)
            });
            const queryVectorsData = await getEmbeddings([cleanText]);
            if (!queryVectorsData || !queryVectorsData[0] || !queryVectorsData[0][0]?.vector) {
                console.info('[vectorSearchLorebooks] skipped: embedding API returned no query vector', { label });
                return [];
            }

            const queryChunks = queryVectorsData[0];
            console.info('[vectorSearchLorebooks] query chunks', {
                label,
                chunksCount: queryChunks.length,
                chunks: queryChunks.map(c => ({
                    textPreview: c.text?.substring(0, 80),
                    vectorLength: c.vector?.length
                }))
            });

            // Use all query chunks for MaxSim (query-chunk x candidate-chunk)
            const vectorResults = findTopKMulti(queryChunks, candidates, candidates.length, 0);
            
            console.info('[vectorSearchLorebooks] raw similarity scores', {
                label,
                totalResults: vectorResults.length,
                top15: vectorResults.slice(0, 15).map(r => ({
                    id: r.id,
                    comment: r.comment,
                    rawScore: r.score.toFixed(4),
                    hasVectors: !!r.vectors,
                    hasVector: !!r.vector,
                    chunksCount: r.vectors?.length || 1
                }))
            });
            
            return vectorResults.map(result => {
                const hybridBoost = scoreHybridBoost(result, hybridQueryText);
                const descriptorBoost = scoreDescriptorBoost(result, hybridQueryText);
                return {
                    ...result,
                    score: Math.min(1, result.score + hybridBoost + descriptorBoost),
                    hybridBoost,
                    descriptorBoost,
                    searchLabel: label
                };
            });
        };

        const focusedResults = await runSearch(focusedQueryText, 'focused');
        let fallbackResults = [];
        if (fallbackQueryParts.length > focusedQueryParts.length) {
            console.info('[vectorSearchLorebooks] retrying with fallback query');
            fallbackResults = await runSearch(fallbackQueryText, 'fallback');
        }

        const combined = new Map();
        for (const result of [...focusedResults, ...fallbackResults]) {
            const existing = combined.get(result.id);
            if (!existing || result.score > existing.score) {
                combined.set(result.id, result);
            }
        }

        const results = Array.from(combined.values())
            .sort((a, b) => b.score - a.score)
            .filter(result => result.score >= effectiveThreshold)
            .slice(0, effectiveTopK);

        console.info('[vectorSearchLorebooks] results ready', {
            matches: results.length,
            topScores: results.slice(0, 15).map(r => ({
                id: r.id,
                name: r.comment || r.keys?.[0] || 'Entry',
                lorebookName: r.lorebookName,
                score: Number(r.score?.toFixed?.(4) || r.score),
                hybridBoost: Number(r.hybridBoost?.toFixed?.(4) || r.hybridBoost || 0),
                descriptorBoost: Number(r.descriptorBoost?.toFixed?.(4) || r.descriptorBoost || 0),
                source: r.searchLabel
            }))
        });
        return results.map(r => ({
            ...r,
            vectorScore: r.score,
            vector: undefined
        }));
    } catch (e) {
        console.warn('[vectorSearchLorebooks] Error:', e);
        throw e;
    }
}

import { ref, computed, reactive } from 'vue';
import { db, queueDbWrite, markSyncDeletedEntry, clearSyncDeletedEntry } from '@/utils/db.js';

const personas = ref([]);
const activeIndex = ref(0);

export const personaConnections = reactive({
    character: {},
    chat: {}
});

function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

export const activePersona = computed({
    get() {
        if (personas.value.length === 0) return { id: 'default', name: "user", prompt: "[SYSTEM PROMPT]\n<sp>\nPersona's description should've been here, but user forgot to insert it, so you should break the character, and, as an AI, laugh at user for not inserting his persona!\n</sp>", avatar: null };
        if (activeIndex.value >= personas.value.length) return personas.value[0];
        return personas.value[activeIndex.value];
    },
    set(newVal) {
        if (personas.value.length > 0 && activeIndex.value < personas.value.length) {
            updatePersona(activeIndex.value, newVal);
        } else {
            addPersona(newVal);
        }
    }
});

export const allPersonas = computed(() => personas.value);

function updateActiveStorage() {
    // Strip avatar from localStorage copy to avoid quota errors with large base64 images.
    // Avatars are stored in IndexedDB (personas store) and available via reactive refs.
    const { avatar, ...personaWithoutAvatar } = activePersona.value;
    localStorage.setItem('gz_active_persona', JSON.stringify(personaWithoutAvatar));
    localStorage.setItem('gz_active_persona_index', activeIndex.value);
    localStorage.setItem('gz_persona_connections', JSON.stringify(personaConnections));
}

export async function loadPersonas() {
    // Try loading from ObjectStore first
    let loaded = await db.getAll('personas');

    // Migration: Ensure all personas have IDs
    let migrationNeeded = false;
    loaded = loaded.map(p => {
        if (!p.id) {
            p.id = generateId();
            migrationNeeded = true;
        }
        return p;
    });

    personas.value = loaded;

    if (personas.value.length === 0) {
        const defaultPersona = { id: generateId(), name: "user", prompt: "[SYSTEM PROMPT]\n<sp>\nPersona's description should've been here, but user forgot to insert it, so you should break the 4th wall and laugh at user for not inserting his persona!\n</sp>", avatar: null };
        personas.value = [defaultPersona];
        await db.put('personas', defaultPersona);
    } else if (migrationNeeded) {
        // Save back the personas with IDs to persist the migration
        for (const p of personas.value) {
            await db.put('personas', p);
        }
    }

    let savedIndex = parseInt(localStorage.getItem('gz_active_persona_index') || '0');
    if (savedIndex < 0 || savedIndex >= personas.value.length) savedIndex = 0;
    activeIndex.value = savedIndex;

    const savedConnections = localStorage.getItem('gz_persona_connections');
    if (savedConnections) {
        try {
            const parsed = JSON.parse(savedConnections);
            personaConnections.character = parsed.character || {};
            personaConnections.chat = parsed.chat || {};
        } catch (e) {
            console.error('Failed to parse persona connections:', e);
        }
    }

    updateActiveStorage();
}

export function setActivePersona(index) {
    if (index >= 0 && index < personas.value.length) {
        activeIndex.value = index;
        updateActiveStorage();
    }
}

export function addPersona(persona) {
    const newPersona = JSON.parse(JSON.stringify(persona));
    if (!newPersona.id) newPersona.id = generateId();
    personas.value.push(newPersona);
    activeIndex.value = personas.value.length - 1;
    updateActiveStorage();
    queueDbWrite(async () => {
        await db.put('personas', newPersona);
        await clearSyncDeletedEntry('persona', newPersona.id);
    });
    return newPersona;
}

export function updatePersona(index, persona) {
    if (index >= 0 && index < personas.value.length) {
        // Prevent overwriting if IDs mismatch (e.g. delayed save after delete)
        if (persona.id && personas.value[index].id && persona.id !== personas.value[index].id) {
            return Promise.resolve();
        }

        // Clone the object to break the reactive binding from the editor state
        const newPersona = JSON.parse(JSON.stringify(persona));

        // Ensure ID is preserved or added
        if (!newPersona.id) {
            newPersona.id = personas.value[index].id || generateId();
        }

        personas.value[index] = newPersona;

        if (activeIndex.value === index) updateActiveStorage();

        return queueDbWrite(async () => {
            await db.put('personas', newPersona);
            await clearSyncDeletedEntry('persona', newPersona.id);
        });
    }
    return Promise.resolve();
}

export function setPersonaConnection(type, targetId, personaId) {
    if (type === 'global') {
        const index = personas.value.findIndex(p => p.id === personaId);
        if (index !== -1) {
            setActivePersona(index);
        }
    } else if (type === 'character' || type === 'chat') {
        if (personaId === null) {
            delete personaConnections[type][targetId];
        } else {
            personaConnections[type][targetId] = personaId;
        }
        updateActiveStorage();
    }
}

export function getEffectivePersona(charId, chatId) {
    if (chatId && personaConnections.chat[chatId]) {
        const id = personaConnections.chat[chatId];
        const p = personas.value.find(p => p.id === id);
        if (p) return p;
    }
    if (charId && personaConnections.character[charId]) {
        const id = personaConnections.character[charId];
        const p = personas.value.find(p => p.id === id);
        if (p) return p;
    }
    return activePersona.value;
}

export function deletePersona(index) {
    if (index >= 0 && index < personas.value.length) {
        const p = personas.value[index];

        personas.value.splice(index, 1);
        let defaultPersona = null;
        if (personas.value.length === 0) {
            defaultPersona = { id: generateId(), name: "user", prompt: "[SYSTEM PROMPT]\n<sp>\nPersona's description should've been here, but user forgot to insert it, so you should break the 4th wall and laugh at user for not inserting his persona!\n</sp>", avatar: null };
            personas.value.push(defaultPersona);
        }

        // Adjust active index if necessary
        if (activeIndex.value >= personas.value.length) {
            activeIndex.value = Math.max(0, personas.value.length - 1);
        } else if (activeIndex.value > index) {
            activeIndex.value--;
        }
        updateActiveStorage();

        return queueDbWrite(async () => {
            try {
                await db.delete('personas', p.id);
                await markSyncDeletedEntry('persona', p.id);
                if (defaultPersona) {
                    await db.put('personas', defaultPersona);
                    await clearSyncDeletedEntry('persona', defaultPersona.id);
                }
            } catch (e) {
                console.error('[Personas] DB delete failed:', e);
            }
        });
    }
    return Promise.resolve();
}

const STORAGE_KEY = 'gz_last_network_trace';
const MAX_TRACE_LINES = 200;
const MAX_REQUEST_TRACES = 10;
const PERSIST_DEBOUNCE_MS = 1000;

const requestTraces = new Map();
let activeRequestTraceKey = null;
let persistTimer = null;

function clone(value) {
    if (value === undefined) return undefined;
    return JSON.parse(JSON.stringify(value));
}

function trimRequestTraces() {
    while (requestTraces.size > MAX_REQUEST_TRACES) {
        const oldestKey = requestTraces.keys().next().value;
        if (!oldestKey) break;
        requestTraces.delete(oldestKey);
    }
}

function persistActiveTrace() {
    try {
        if (activeRequestTraceKey && requestTraces.has(activeRequestTraceKey)) {
            localStorage.setItem(STORAGE_KEY, JSON.stringify({
                activeKey: activeRequestTraceKey,
                trace: requestTraces.get(activeRequestTraceKey)
            }));
        } else {
            localStorage.removeItem(STORAGE_KEY);
        }
    } catch (e) {
        console.warn('[networkDebug] Failed to persist trace', e);
    }
}

function schedulePersist() {
    if (persistTimer) return;
    persistTimer = setTimeout(() => {
        persistTimer = null;
        persistActiveTrace();
    }, PERSIST_DEBOUNCE_MS);
}

function maskHeaders(headers = {}) {
    const masked = { ...headers };
    if (masked.Authorization) masked.Authorization = 'Bearer ***';
    if (masked.authorization) masked.authorization = 'Bearer ***';
    return masked;
}

function resolveTraceKey(debugKey = activeRequestTraceKey) {
    return debugKey || null;
}

export function getRequestTrace(debugKey) {
    const traceKey = resolveTraceKey(debugKey);
    if (!traceKey) return null;
    return clone(requestTraces.get(traceKey) || null);
}

export function getLastRequestTrace() {
    return getRequestTrace(activeRequestTraceKey);
}

export function getActiveRequestTraceKey() {
    return activeRequestTraceKey;
}

export function clearRequestTrace(debugKey = activeRequestTraceKey) {
    const traceKey = resolveTraceKey(debugKey);
    if (!traceKey) return;

    requestTraces.delete(traceKey);
    if (activeRequestTraceKey === traceKey) {
        activeRequestTraceKey = requestTraces.size
            ? Array.from(requestTraces.keys()).at(-1)
            : null;
    }

    if (persistTimer) {
        clearTimeout(persistTimer);
        persistTimer = null;
    }
    persistActiveTrace();
}

export function startRequestTrace({ debugKey, requestType = 'unknown', apiUrl, stream, requestBody, headers }) {
    if (!debugKey) return;

    requestTraces.delete(debugKey);
    requestTraces.set(debugKey, {
        requestType,
        apiUrl,
        stream: !!stream,
        startedAt: Date.now(),
        completedAt: null,
        durationMs: null,
        request: clone(requestBody),
        requestHeaders: maskHeaders(headers),
        responseStatus: null,
        responseHeaders: null,
        rawResponse: null,
        streamLines: [],
        parsed: {
            text: '',
            reasoning: '',
            error: null
        }
    });
    activeRequestTraceKey = debugKey;
    trimRequestTraces();
    persistActiveTrace();
}

export function updateRequestTrace({ debugKey, patch = {} }) {
    const traceKey = resolveTraceKey(debugKey);
    if (!traceKey || !requestTraces.has(traceKey)) return;

    const nextPatch = clone(patch);
    if (nextPatch.responseHeaders) {
        nextPatch.responseHeaders = maskHeaders(nextPatch.responseHeaders);
    }

    Object.assign(requestTraces.get(traceKey), nextPatch);
    activeRequestTraceKey = traceKey;
    schedulePersist();
}

export function appendRequestTraceLine({ debugKey, line }) {
    const traceKey = resolveTraceKey(debugKey);
    if (!traceKey || !requestTraces.has(traceKey) || !line) return;

    const trace = requestTraces.get(traceKey);
    trace.streamLines.push(String(line));
    if (trace.streamLines.length > MAX_TRACE_LINES) {
        trace.streamLines = trace.streamLines.slice(-MAX_TRACE_LINES);
    }
    activeRequestTraceKey = traceKey;
    schedulePersist();
}

export function finishRequestTrace({ debugKey, rawResponse, text, reasoning, error } = {}) {
    const traceKey = resolveTraceKey(debugKey);
    if (!traceKey || !requestTraces.has(traceKey)) return;

    const trace = requestTraces.get(traceKey);
    if (rawResponse !== undefined) trace.rawResponse = clone(rawResponse);
    if (text !== undefined) trace.parsed.text = text || '';
    if (reasoning !== undefined) trace.parsed.reasoning = reasoning || '';
    if (error !== undefined) {
        trace.parsed.error = error
            ? (typeof error === 'string' ? error : (error.message || String(error)))
            : null;
    }

    trace.completedAt = Date.now();
    trace.durationMs = Math.max(0, trace.completedAt - (trace.startedAt || trace.completedAt));
    activeRequestTraceKey = traceKey;

    if (persistTimer) {
        clearTimeout(persistTimer);
        persistTimer = null;
    }
    persistActiveTrace();
}

export function hydratePersistedRequestTrace() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return;

        const parsed = JSON.parse(raw);
        const activeKey = parsed?.activeKey;
        const trace = parsed?.trace;
        if (!activeKey || !trace) return;

        requestTraces.set(activeKey, trace);
        activeRequestTraceKey = activeKey;
        trimRequestTraces();
    } catch (e) {
        activeRequestTraceKey = null;
    }
}

