    const handleGlobalError = (msg, url, lineNo, columnNo, error) => {
        // Suppress errors explicitly marked or originating from Shadow DOM interactions
        const isRecentShadowInteraction = window._lastShadowInteraction && (Date.now() - window._lastShadowInteraction < 100);
        if (error && error.isShadowError) return true;
        if (isRecentShadowInteraction) return true;

        // Suppress reference errors that likely come from shadow DOM element inline handlers
        if (typeof msg === 'string' && (msg.includes('ReferenceError') || msg.includes('Shadow Error')) && isRecentShadowInteraction) return true;

        let details = "";
        let finalTitle = 'Uncaught Exception';

        if (msg === 'Script error.') {
            finalTitle = 'CORS / Cross-Origin Error';
            details = "Script error (masked by browser). <br><br><b>Potential reasons:</b><br>- Error in a cross-origin script.<br>- Script not served with correct CORS headers.<br>- iOS security restriction.<br><br>Check remote debugger/Safari Web Inspector for actual details.";
        } else {
            details = `${msg}<br>URL: ${url}<br>Line: ${lineNo} Column: ${columnNo}<br>Stack: ${error ? (error.stack || 'N/A').replace(/\n/g, '<br>') : 'N/A'}`;
        }

        showError(finalTitle, details);
        return false;
    };

    // Use both window.onerror and addEventListener('error') for maximum coverage
    window.onerror = handleGlobalError;

    window.addEventListener('error', (event) => {
        if (event.error) {
            handleGlobalError(event.message, event.filename, event.lineno, event.colno, event.error);
        } else if (event.message === 'Script error.') {
            handleGlobalError('Script error.', '', 0, 0, null);
        }
    }, true);

    window.onunhandledrejection = function (event) {
        const reason = event.reason;
        const isRecentShadowInteraction = window._lastShadowInteraction && (Date.now() - window._lastShadowInteraction < 100);
        if ((reason && reason.isShadowError) || isRecentShadowInteraction) return; // Suppress

        let details = reason;
        if (reason instanceof Error) {
            details = `${reason.message}\nStack: ${reason.stack}`;
        } else {
            try {
                details = JSON.stringify(reason);
            } catch (e) {
                details = String(reason);
            }
        }
        showError('Unhandled Promise Rejection', String(details).replace(/\n/g, '<br>'));
    };

    window.addEventListener('vue-error', (event) => {
        const { err, info } = event.detail;
        const details = `${err.message}<br>Component Info: ${info}<br>Stack: ${(err.stack || 'N/A').replace(/\n/g, '<br>')}`;
        showError('Vue Error', details);
    });
}

import { getApiReasoningTags } from '@/core/config/APISettings.js';

let pickCount = 0;

export function replaceMacros(text, char, persona, sessionVarsIn = null, notifyObj = null) {
    if (!text) return "";

    // --- Comments ---
    // Multi-line scoped: {{ // }} ... {{ /// }}
    let result = text.replace(/\{\{\s*\/\/\s*\}\}[\s\S]*?\{\{\s*\/\/\/\s*\}\}/g, '');
    // Single-line: {{// comment}}
    result = result.replace(/\{\{\/\/[^}]*\}\}/g, '');

    const charName = char ? (char.macro_name || char.name) : "Character";
    const charDesc = char ? (char.description || char.desc || "") : "";
    const charScenario = char ? (char.scenario || "") : "";
    const charPersonality = char ? (char.personality || "") : "";
    const charMesExample = char ? (char.mes_example || "") : "";

    const userName = persona ? persona.name : "User";
    const userPersona = persona ? (persona.prompt || "") : "";

    result = result.replace(/{{char}}/gi, charName)
        .replace(/{{description}}/gi, charDesc)
        .replace(/{{scenario}}/gi, charScenario)
        .replace(/{{personality}}/gi, charPersonality)
        .replace(/{{mesExamples}}/gi, charMesExample)
        .replace(/{{user}}/gi, userName)
        .replace(/{{persona}}/gi, userPersona);

    // {{trim}}
    if (result.includes("{{trim}}")) {
        result = result.replace(/{{trim}}/gi, "").trim();
    }

    const charId = char?.id || "default";
    const sessionId = char?.sessionId || "current";

    // If sessionVars not provided (main thread), load from localStorage
    const ownVars = sessionVarsIn === null;
    const sessionVars = ownVars ? _getSessionVars(charId, sessionId) : sessionVarsIn;
    let varsChanged = false;

    // {{setvar::name::value}}
    result = result.replace(/{{setvar::([\s\S]*?)::([\s\S]*?)}}/gi, (match, name, value) => {
        sessionVars[name] = value;
        varsChanged = true;
        return "";
    });

    // {{setglobalvar::name::value}}
    result = result.replace(/{{setglobalvar::([\s\S]*?)::([\s\S]*?)}}/gi, (match, name, value) => {
        _setGlobalVar(name, value);
        return "";
    });

    // {{getvar::name}}
    result = result.replace(/{{getvar::([\s\S]*?)}}/gi, (match, name) => {
        return sessionVars[name] !== undefined ? sessionVars[name] : "";
    });

    // {{getglobalvar::name}}
    result = result.replace(/{{getglobalvar::([\s\S]*?)}}/gi, (match, name) => {
        const val = _getGlobalVar(name);
        return val !== null ? val : "";
    });

    // {{lumiaDef}}, {{lumiaOOC}}, {{loomRetrofits}}, etc. - custom macros from preset
    // These are treated as global variables set via setglobalvar
    result = result.replace(/\{\{(lumiaDef|lumiaOOC|lumiaOOCErotic|lumiaOOCEroticBleed|lumiaPersonality|loomRetrofits|loomStyle|loomSummary|loomUtils|sim_tracker|suggest)\}\}/gi, (match, name) => {
        const val = _getGlobalVar(name);
        return val !== null ? val : match; // return original macro if not found
    });

    // {{random::a::b::c}}
    result = result.replace(/{{random::(.*?)}}/gi, (match, optionsStr) => {
        const options = optionsStr.split("::");
        return options[Math.floor(Math.random() * options.length)];
    });

    // {{pick::a::b::c}}
    result = result.replace(/{{pick::(.*?)}}/gi, (match, optionsStr) => {
        const options = optionsStr.split("::");
        const version = sessionVars.__pick_version || 0;
        const seed = `${charId}_${sessionId}_pick_${pickCount++}_v${version}`;
        const hash = _simpleHash(seed);
        return options[hash % options.length];
    });

    // {{roll::1d20}}
    result = result.replace(/{{roll::(.*?)}}/gi, (match, dice) => {
        return _rollDice(dice);
    });

    // {{date}} / {{time}} / {{weekday}} - current datetime
    const now = new Date();
    result = result.replace(/\{\{date\}\}/gi, () => now.toLocaleDateString());
    result = result.replace(/\{\{time\}\}/gi, () => now.toLocaleTimeString());
    result = result.replace(/\{\{weekday\}\}/gi, () => now.toLocaleDateString('en-US', { weekday: 'long' }));

    // {{reasoningPrefix}} / {{reasoningSuffix}} - reasoning tags from sessionVars or localStorage
    result = result.replace(/\{\{reasoningPrefix\}\}/gi, () => {
        return sessionVars.reasoningPrefix || getApiReasoningTags().start;
    });
    result = result.replace(/\{\{reasoningSuffix\}\}/gi, () => {
        return sessionVars.reasoningSuffix || getApiReasoningTags().end;
    });

    // --- Escaping: \{\{ → {{ and \}\} → }} ---
    result = result.replace(/\\\{/g, '{').replace(/\\\}/g, '}');

    if (varsChanged) {
        if (notifyObj) notifyObj.varsChanged = true;
        if (ownVars) _saveSessionVars(charId, sessionId, sessionVars);
    }

    return result;
}

function _getSessionVars(charId, sessionId) {
    const key = `gz_vars_${charId}_${sessionId}`;
    try {
        return JSON.parse(localStorage.getItem(key)) || {};
    } catch (e) {
        return {};
    }
}

function _saveSessionVars(charId, sessionId, vars) {
    const key = `gz_vars_${charId}_${sessionId}`;
    localStorage.setItem(key, JSON.stringify(vars));
}

function _getGlobalVar(name) {
    try {
        const globalVars = JSON.parse(localStorage.getItem('gz_global_vars') || '{}');
        return globalVars[name] !== undefined ? globalVars[name] : null;
    } catch (e) {
        return null;
    }
}

function _setGlobalVar(name, value) {
    try {
        const globalVars = JSON.parse(localStorage.getItem('gz_global_vars') || '{}');
        globalVars[name] = value;
        localStorage.setItem('gz_global_vars', JSON.stringify(globalVars));
    } catch (e) { }
}

function _simpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash |= 0;
    }
    return Math.abs(hash);
}

function _rollDice(dice) {
    const match = dice.match(/(\d+)d(\d+)/i);
    if (!match) return dice;
    const count = parseInt(match[1]);
    const sides = parseInt(match[2]);
    let total = 0;
    for (let i = 0; i < count; i++) {
        total += Math.floor(Math.random() * sides) + 1;
    }
    return total.toString();
}

/**
 * Pure JS LMDB reader for Isar-based Tavo backups.
 * Heuristically extracts JSON and texts without WebAssembly or native bindings.
 */
import JSZip from 'jszip';
import { db } from '@/utils/db.js';
import { importSillyTavernChat } from '@/core/services/chatImporter.js';
import { convertSTPreset } from '@/core/services/presetImportService.js';

// Basic Type Mapping from Isar Schema (extracted via heuristic)
const TYPE_NAMES = {
    0x0004: "character",
    0x0018: "conversation",
    0x001c: "model_setting",
    0x0024: "endpoint",
    0x0028: "persona_ref",
    0x0038: "message",
    0x0040: "chat_theme",
    0x0048: "preset",
    0x0058: "ltm_settings",
    0x0060: "ltm",
    0x0064: "regex",
    0x006c: "regex_conversation_ref",
    0x0080: "lorebook"
};

function extractStringsAndJson(uint8Array) {
    const items = [];
    let i = 0;
    const len = uint8Array.length;
    const decoder = new TextDecoder("utf-8");

    while (i < len) {
        if (uint8Array[i] >= 32 || uint8Array[i] === 10 || uint8Array[i] === 13 || uint8Array[i] === 9) {
            const start = i;
            while (i < len && (uint8Array[i] >= 32 || uint8Array[i] === 10 || uint8Array[i] === 13 || uint8Array[i] === 9)) {
                i++;
            }
            try {
                const text = decoder.decode(uint8Array.subarray(start, i)).trim();
                if (text.length >= 2) {
                    if (text.startsWith("[") || text.startsWith("{")) {
                        try {
                            const parsed = JSON.parse(text);
                            items.push({ type: "json", data: parsed });
                            continue;
                        } catch (e) {
                            // fall back to text
                        }
                    }
                    if (!text.includes('\ufffd')) {
                        items.push({ type: "text", data: text });
                    }
                }
            } catch (e) {
                // Ignore decoding errors
            }
        } else {
            i++;
        }
    }
    return items;
}

export function parseTavoLMDB(arrayBuffer) {
    const dv = new DataView(arrayBuffer);
    const buffer = new Uint8Array(arrayBuffer);
    const pageSize = 4096;

    const categories = {};
    for (const k of Object.values(TYPE_NAMES)) categories[k] = new Map();

    let bigCount = 0;

    for (let pOffset = 0; pOffset < buffer.length; pOffset += pageSize) {
        if (pOffset + 16 > buffer.length) break;
        const flags = dv.getUint16(pOffset + 10, true);
        if ((flags & 0x02) === 0x02) { // P_LEAF
            const lower = dv.getUint16(pOffset + 12, true);
            const numNodes = (lower - 16) / 2;

            for (let i = 0; i < numNodes; i++) {
                const nodeOffset = dv.getUint16(pOffset + 16 + (i * 2), true);
                if (nodeOffset === 0) continue;

                const ptr = pOffset + nodeOffset;

                const mn_dsize = dv.getUint32(ptr, true);
                const mn_flags = dv.getUint16(ptr + 4, true);
                const mn_ksize = dv.getUint16(ptr + 6, true);

                // Ensure valid Isar key (18 prefix) -> 1 byte 0x18 + 7 bytes
                if (mn_ksize >= 8 && buffer[ptr + 8] === 0x18) {
                    const type_id = (buffer[ptr + 10] << 8) | buffer[ptr + 11];
                    const type_name = TYPE_NAMES[type_id];
                    if (!type_name) continue;

                    const entity_id = dv.getUint32(ptr + 12, false); // BIG ENDIAN

                    let dataBuffer = null;
                    const keyOffset = ptr + 8;
                    const dataOffset = keyOffset + mn_ksize;

                    // Inline data
                    if (mn_flags === 0) {
                        dataBuffer = buffer.subarray(dataOffset, dataOffset + mn_dsize);
                    }
                    // Overflow pages (F_BIGDATA)
                    else if (mn_flags === 1) {
                        bigCount++;
                        const pgno = dv.getUint32(dataOffset, true);
                        if (pgno * pageSize < buffer.length) {
                            const ovfOffset = pgno * pageSize;
                            const ovfFlags = dv.getUint16(ovfOffset + 10, true);
                            if ((ovfFlags & 0x04) === 0x04) { // P_OVERFLOW
                                dataBuffer = buffer.subarray(ovfOffset + 16, ovfOffset + 16 + mn_dsize);
                            }
                        }
                    }

                    if (dataBuffer) {
                        const fields = extractStringsAndJson(dataBuffer);
                        const entry = { entity_id, fields };

                        if (type_name === 'message' && dataBuffer.length >= 88) {
                            try {
                                const msgDv = new DataView(dataBuffer.buffer, dataBuffer.byteOffset, dataBuffer.byteLength);
                                entry.timestamp = Number(msgDv.getBigInt64(48, true));
                                entry.conversationId = Number(msgDv.getBigInt64(64, true));
                                entry.characterId = Number(msgDv.getBigInt64(80, true));
                            } catch (e) { }
                        }

                        categories[type_name].set(entity_id, entry);
                    }
                }
            }
        }
    }

    // Convert maps back to arrays
    for (const k in categories) {
        categories[k] = Array.from(categories[k].values());
    }

    // Group chats
    const chats = [];
    if (categories.conversation && categories.message) {
        const msgByConv = {};
        for (const msg of categories.message) {
            if (msg.conversationId) {
                if (!msgByConv[msg.conversationId]) msgByConv[msg.conversationId] = [];
                msgByConv[msg.conversationId].push(msg);
            }
        }
        for (const conv of categories.conversation) {
            const cid = conv.entity_id;
            const msgs = msgByConv[cid] || [];
            msgs.sort((a, b) => (a.timestamp || a.entity_id) - (b.timestamp || b.entity_id));
            chats.push({ conversation: conv, messages: msgs });
        }
    }

    return { categories, chats };
}

/**
 * Base64 decoder for shared prefs decoding
 */
export async function decodeSharedPreferences(prefsBuffer) {
    const text = new TextDecoder("utf-8").decode(prefsBuffer);
    try {
        const prefs = JSON.parse(text);
        const decoded = {};
        for (const [k, v] of Object.entries(prefs)) {
            if (typeof v === 'string') {
                try {
                    const str = atob(v);
                    try {
                        decoded[k] = JSON.parse(str);
                    } catch (e) {
                        decoded[k] = str;
                    }
                } catch {
                    decoded[k] = v;
                }
            } else if (Array.isArray(v)) {
                decoded[k] = v.map(item => {
                    if (typeof item === 'string') {
                        try {
                            const str = atob(item);
                            try { return JSON.parse(str); } catch { return str; }
                        } catch { return item; }
                    }
                    return item;
                });
            } else {
                decoded[k] = v;
            }
        }
        return decoded;
    } catch {
        return {};
    }
}

/**
 * Imports a Tavo (.tbk) Backup internally inside Glaze via LMDB heuristic parsing.
 * @param {File|Blob} zipFile
 * @param {Function} [onProgress]
 */
export async function importTavoBackupFromZip(zipFile, onProgress) {
    const progress = (msg) => { if (onProgress) onProgress(msg); };
    const result = { characters: 0, lorebooks: 0, presets: 0, chats: 0, errors: [] };

    const zip = await JSZip.loadAsync(zipFile);

    // ── Clear existing DB before import ─────────────────────────────────────
    progress('clearing');
    const database = await db.open();
    await new Promise((res, rej) => {
        const tx = database.transaction(['characters', 'personas', 'keyvalue'], 'readwrite');
        tx.objectStore('characters').clear();
        tx.objectStore('personas').clear();
        tx.objectStore('keyvalue').clear();

        tx.oncomplete = res;
        tx.onerror = () => rej(tx.error);
    });
    database.close();
    localStorage.removeItem('silly_cradle_presets');
    localStorage.removeItem('regex_scripts');

    const mdbFile = Object.keys(zip.files).find(p => p.toLowerCase().endsWith('data.mdb'));
    if (!mdbFile) throw new Error("No data.mdb found in Tavo backup zip.");

    progress('reading DB');
    const mdbBuffer = await zip.files[mdbFile].async('arraybuffer');
    const tavoData = parseTavoLMDB(mdbBuffer);

    // Helper: resolve a charaCard/... path from the ZIP and return a base64 data URL
    async function readAvatarFromZip(charaCardPath) {
        if (!charaCardPath || !charaCardPath.includes('/')) return null;
        // Strip leading path component and look in CharacterCards/
        const filename = charaCardPath.split('/').pop();
        // Try to find the file in the zip (case-insensitive, any folder)
        const zipKey = Object.keys(zip.files).find(k =>
            k.toLowerCase().endsWith(('CharacterCards/' + filename).toLowerCase()) ||
            k.toLowerCase().endsWith(filename.toLowerCase())
        );
        if (!zipKey) return null;
        try {
            const blob = await zip.files[zipKey].async('blob');
            return await new Promise((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result);
                reader.onerror = () => resolve(null);
                reader.readAsDataURL(blob);
            });
        } catch (e) {
            return null;
        }
    }

    // Process Personas
    progress('personas');
    if (tavoData.categories.persona_ref && tavoData.categories.persona_ref.length > 0) {
        for (const pref of tavoData.categories.persona_ref) {
            try {
                // Filter out empty strings
                const strings = pref.fields.filter(f => f.type === 'text' && f.data.trim().length > 0).map(f => f.data);
                if (strings.length < 2) continue;

                // Avatar is stored as charaCard/...
                const rawAvatar = strings.find(s => s.startsWith('charaCard/'));
                const textOnly = strings.filter(s => s !== rawAvatar);

                let prompt = "";
                let name = "User Persona";
                if (textOnly.length >= 2) {
                    // Usually name is much shorter than description
                    textOnly.sort((a, b) => b.length - a.length);
                    prompt = textOnly[0];
                    name = textOnly[textOnly.length - 1]; // smallest
                } else if (textOnly.length > 0) {
                    name = textOnly[0];
                }

                const persona = {
                    id: Date.now().toString(36) + Math.random().toString(36).substr(2),
                    prompt: prompt || "",
                    name: name || "User Persona",
                    avatar: rawAvatar ? await readAvatarFromZip(rawAvatar) : null
                };
                await db.put('personas', persona);
            } catch (err) {
                result.errors.push(`Tavo Persona: ${err.message}`);
            }
        }
    }

    // Process APIs
    progress('apis');
    if (tavoData.categories.endpoint && tavoData.categories.endpoint.length > 0) {
        const existingApiPresets = await db.get('gz_api_connection_presets') || [];
        for (const ep of tavoData.categories.endpoint) {
            try {
                // Empty strings are often spacing, keep robust logic
                const strings = ep.fields.filter(f => f.type === 'text' && f.data.trim().length > 0).map(f => f.data);
                if (strings.length < 4) continue;

                // Identify endpoint URL (first string that starts with http)
                const urlIndex = strings.findIndex(s => s.startsWith('http://') || s.startsWith('https://'));
                const baseIndex = urlIndex !== -1 ? urlIndex : 0;

                const preset = {
                    id: 'tavo_' + Date.now().toString(36) + Math.random().toString(36).substr(2),
                    endpoint: strings[baseIndex] || "",
                    model: strings[baseIndex + 2] || "",
                    key: strings[baseIndex + 3] || "",
                    name: strings.length > baseIndex + 4 ? strings[baseIndex + 4] : (strings[baseIndex] || "Tavo Endpoint"),
                    max_tokens: '8000',
                    context: '32000',
                    temp: '0.7',
                    topp: '0.9',
                    stream: true
                };
                if (!existingApiPresets.some(p => p.endpoint === preset.endpoint && p.key === preset.key)) {
                    existingApiPresets.push(preset);
                }
            } catch (err) {
                result.errors.push(`Tavo API: ${err.message}`);
            }
        }
        await db.set('gz_api_connection_presets', existingApiPresets);
    }

    // Process Regexes
    progress('regexes');
    if (tavoData.categories.regex && tavoData.categories.regex.length > 0) {
        let globalScripts = [];
        try { globalScripts = JSON.parse(localStorage.getItem('regex_scripts')) || []; } catch (e) { }
        for (const regGroup of tavoData.categories.regex) {
            try {
                const texts = regGroup.fields.filter(f => f.type === 'text' && f.data.trim().length > 0).map(f => f.data);
                const jsons = regGroup.fields.filter(f => f.type === 'json').map(f => f.data);

                // Fallback: sometimes regex JSON contains complex characters that make tavoBackupReader fail
                const unparsed = regGroup.fields.filter(f => f.type === 'text' && f.data.trim().startsWith('[') && f.data.includes('"findRegex"'));
                for (const u of unparsed) {
                    try { jsons.push(JSON.parse(u.data)); } catch (e) { }
                }

                const groupName = texts.length > 0 ? texts[texts.length - 1] : '';

                for (const jsonBlock of jsons) {
                    if (Array.isArray(jsonBlock)) {
                        for (const rule of jsonBlock) {
                            if (rule.identifier && rule.name) {
                                const finalName = groupName ? `[${groupName}] ${rule.name}` : rule.name;
                                globalScripts.push({
                                    id: 'tavo_' + rule.identifier,
                                    name: finalName,
                                    regex: rule.findRegex || "",
                                    replacement: rule.replaceString || "",
                                    trimOut: Array.isArray(rule.trimStrings) ? rule.trimStrings.join('\n') : "",
                                    placement: [1, 2],
                                    disabled: rule.enabled === false,
                                    markdownOnly: false,
                                    runOnEdit: false,
                                    substituteRegex: rule.substitution === "none" ? 0 : 1,
                                    ephemerality: [1, 2],
                                    minDepth: rule.minDepth || null,
                                    maxDepth: rule.maxDepth || null
                                });
                            }
                        }
                    }
                }
            } catch (err) {
                result.errors.push(`Tavo Regex: ${err.message}`);
            }
        }
        localStorage.setItem('regex_scripts', JSON.stringify(globalScripts));
    }

    // Process Lorebooks
    progress('lorebooks');
    if (tavoData.categories.lorebook && tavoData.categories.lorebook.length > 0) {
        const existingLorebooksData = await db.get('gz_lorebooks') || { lorebooks: [], settings: {}, activations: {} };
        const existingLorebooks = Array.isArray(existingLorebooksData)
            ? existingLorebooksData
            : (existingLorebooksData.lorebooks || []);

        for (const lb of tavoData.categories.lorebook) {
            try {
                // The entries JSON block is the first json field; the name is the last text field
                const entriesField = lb.fields.find(f => f.type === 'json' && Array.isArray(f.data));
                const nameField = lb.fields.filter(f => f.type === 'text').pop();
                if (!entriesField) continue;

                const lbName = nameField ? nameField.data : 'Tavo Lorebook';
                const entries = entriesField.data.map(e => ({
                    id: 'tavo_' + (e.identifier || Date.now().toString(36) + Math.random().toString(36).substr(2)),
                    keys: Array.isArray(e.keywords) ? e.keywords : [],
                    secondary_keys: Array.isArray(e.secondaryKeywords) ? e.secondaryKeywords : [],
                    content: e.content || '',
                    comment: e.name || '',
                    enabled: e.enabled !== false,
                    constant: e.strategy === 'constant',
                    selectiveLogic: 0,
                    order: 100,
                    probability: typeof e.probability === 'number' ? e.probability : 100,
                    scanDepth: typeof e.scanDepth === 'number' ? e.scanDepth : 2,
                    caseSensitive: e.caseSensitive ?? false,
                    matchWholeWords: e.matchWholeWord ?? false,
                    sticky: e.sticky || 0,
                    cooldown: e.cooldown || 0,
                    delay: e.delay || 0,
                    group: e.groupName || '',
                    preventRecursion: e.preventRecursion || false,
                    excludeRecursion: e.excludeRecursion || false,
                }));

                existingLorebooks.push({
                    id: 'tavo_lb_' + lb.entity_id,
                    name: lbName,
                    enabled: true,
                    entries,
                });
                result.lorebooks++;
            } catch (err) {
                result.errors.push(`Tavo Lorebook: ${err.message}`);
            }
        }

        const saveData = typeof existingLorebooksData === 'object' && !Array.isArray(existingLorebooksData)
            ? { ...existingLorebooksData, lorebooks: existingLorebooks }
            : { lorebooks: existingLorebooks, settings: {}, activations: {} };
        await db.set('gz_lorebooks', saveData);
    }

    // Process Presets
    progress('presets');
    if (tavoData.categories.preset && tavoData.categories.preset.length > 0) {
        const existingPresetsRaw = localStorage.getItem('silly_cradle_presets');
        const existingPresets = existingPresetsRaw ? JSON.parse(existingPresetsRaw) : {};

        for (const preset of tavoData.categories.preset) {
            try {
                // preset.fields usually has a JSON block of prompts and the name at the end
                let promptsJson = null;
                let presetName = "Tavo Preset";
                for (let i = 0; i < preset.fields.length; i++) {
                    const f = preset.fields[i];
                    if (f.type === 'json' && Array.isArray(f.data) && f.data.length > 0 && f.data[0].identifier) {
                        promptsJson = f.data;
                    } else if (f.type === 'text' && f.data.length < 50 && !f.data.includes('{')) {
                        presetName = f.data;
                    }
                }

                if (promptsJson) {
                    const pData = {
                        name: presetName,
                        prompts: promptsJson
                    };
                    const converted = convertSTPreset(pData, presetName);
                    const id = Date.now().toString(36) + Math.random().toString(36).substr(2);
                    converted.id = id;
                    existingPresets[id] = converted;
                    result.presets++;
                }
            } catch (err) {
                result.errors.push(`Tavo Preset: ${err.message}`);
            }
        }
        localStorage.setItem('silly_cradle_presets', JSON.stringify(existingPresets));
    }

    // Process Characters
    progress('characters');
    const charNameToId = {};
    if (tavoData.categories.character && tavoData.categories.character.length > 0) {
        for (const char of tavoData.categories.character) {
            try {
                const strings = char.fields.filter(f => f.type === 'text' && f.data.trim().length > 0).map(f => f.data);
                const jsons = char.fields.filter(f => f.type === 'json').map(f => f.data);

                let charData = { id: Date.now().toString(36) + Math.random().toString(36).substr(2) };

                // If it's a V2 JSON inside
                const v2Json = jsons.find(j => j.spec === 'chara_card_v2' || j.spec === 'chara_card_v3');
                if (v2Json && v2Json.data) {
                    charData = { ...charData, ...v2Json.data };
                    // v2 cards don't embed the avatar path separately; try to find it by name
                    const avatarStr = strings.find(s => s.startsWith('charaCard/'));
                    if (avatarStr) charData.avatar = await readAvatarFromZip(avatarStr);
                } else if (strings.length >= 2) {
                    // Fallback heuristic extraction
                    const avatarStr = strings.find(s => s.startsWith('charaCard/'));
                    if (avatarStr) charData.avatar = await readAvatarFromZip(avatarStr);

                    const rem = strings.filter(s => s !== avatarStr);
                    // Name is consistently the final string field in Tavo's character entity unrolling
                    charData.name = rem.length > 0 ? rem.pop() : "Unknown";

                    // The easiest and most robust way to find Description and First_mes 
                    // from the loosely coupled strings is by length sorting
                    const sortedByLen = [...rem].sort((a, b) => b.length - a.length);
                    charData.description = sortedByLen.length > 0 ? sortedByLen[0] : "";
                    charData.first_mes = sortedByLen.length > 1 ? sortedByLen[1] : "";

                    // Bundle the rest to avoid silent data loss (short descriptions, tags, scenarios)
                    if (sortedByLen.length > 2) {
                        const leftover = sortedByLen.slice(2);

                        // Extract probable tags (short, single-line strings)
                        const probableTags = leftover.filter(s => s.length < 60 && !s.includes('\n') && !s.startsWith('http') && !s.startsWith('charaCard/'));
                        if (probableTags.length > 0) {
                            // SillyTavern and Glaze expect an array of strings for tags
                            charData.tags = probableTags.map(t => t.trim());
                        }

                        // The rest goes to creator_notes
                        const remaining = leftover.filter(s => !probableTags.includes(s) && !s.startsWith('http') && !s.startsWith('charaCard/'));
                        if (remaining.length > 0) {
                            charData.creator_notes = remaining.join("\n\n---\n");
                        }
                    }
                } else {
                    continue; // cannot parse
                }

                if (!charData.name) charData.name = "Unknown";
                await db.saveCharacter(charData);
                charNameToId[char.entity_id] = charData.id;
                result.characters++;
            } catch (err) {
                result.errors.push(`Tavo Character: ${err.message}`);
            }
        }
    }

    // Process Chats
    progress('chats');
    if (tavoData.chats && tavoData.chats.length > 0) {
        for (const chatBlock of tavoData.chats) {
            try {
                const cid = chatBlock.conversation.entity_id;

                const msgs = chatBlock.messages.filter(m => m.fields && m.fields.length > 0);
                if (msgs.length === 0) continue;

                // Find the first AI message to determine which character this chat belongs to.
                // User messages have characterId === 0 in Tavo (not -1).
                const firstCharMsg = msgs.find(m => m.characterId && m.characterId !== 0);
                if (!firstCharMsg) continue;
                const charEntityId = firstCharMsg.characterId;

                const glazeCharId = charNameToId[charEntityId];
                if (!glazeCharId) {
                    continue;
                }

                // Convert messages to ST format JSONL and use existing importer
                const lines = [];
                const metadata = {
                    user_name: "User",
                    character_name: "Char",
                    create_date: new Date().toISOString(),
                    chat_metadata: { exported_from: "Tavo", import_date: Date.now() }
                };
                lines.push(JSON.stringify(metadata));

                for (const tMsg of msgs) {
                    // Find actual text ignoring IDs, hashes, and internal image paths
                    const txt = tMsg.fields.filter(f => f.type === 'text' && f.data.length > 5 && !f.data.startsWith('charaCard/')).map(f => f.data).join("\n");
                    // characterId === 0 or negative means user message in Tavo
                    const isUser = !tMsg.characterId || tMsg.characterId <= 0;
                    const stMsg = {
                        name: isUser ? "User" : "Char",
                        is_user: isUser,
                        is_system: false,
                        send_date: new Date(tMsg.timestamp || Date.now()).toISOString(),
                        mes: txt,
                        extra: {}
                    };
                    lines.push(JSON.stringify(stMsg));
                }

                const blob = new Blob([lines.join("\n")], { type: 'text/plain' });
                await importSillyTavernChat(blob, glazeCharId, null);
                result.chats++;
            } catch (err) {
                result.errors.push(`Tavo Chat: ${err.message}`);
            }
        }
    }

    return result;
}

import { getEffectivePreset } from '@/core/states/presetState.js';
import { applyRegexes } from '@/core/services/regexService.js';

export function cleanText(text) {
    if (!text) return "";
    return text.trim();
}

export function formatText(text, isUser = false, options = {}) {
    if (!text) return "";

    const { charId, sessionId, char, persona, triggeredRegexes } = options;

    // Remove leading/trailing line breaks
    text = cleanText(text);

    // Apply Regex Scripts (Before HTML formatting, simulating ST behavior)
    // 1 corresponds to User Input, 2 corresponds to AI Output
    // 1 corresponds to Alter Chat Display (ephemerality)
    text = applyRegexes(text, isUser ? 1 : 2, 1, { charId, sessionId, char, persona, triggeredRegexes });

    // 1. Allow HTML (No escaping)
    let html = text;

    // 2. Extract Code Blocks (to prevent formatting inside them)
    const codeBlocks = [];
    html = html.replace(/```(\w*)\n?([\s\S]*?)(?:```|$)/g, (match, lang, code) => {
        const isClosed = match.endsWith('```');
        const id = `__CODE_BLOCK_${codeBlocks.length}__`;
        codeBlocks.push({ lang, code, isClosed });
        return id;
    });

    // Extract Style Blocks (to prevent formatting inside them)
    const styleBlocks = [];
    html = html.replace(/<style([\s\S]*?)>([\s\S]*?)(?:<\/style>|$)/gi, (match, attributes, content) => {
        const isClosed = /<\/style>\s*$/i.test(match);
        const id = `__STYLE_BLOCK_${styleBlocks.length}__`;
        // Fix escaped newlines inside style blocks by converting them to real newlines
        content = content.replace(/&lt;br\s*\/?(?:&gt;|>)/gi, '\n');
        styleBlocks.push({ attributes, content, isClosed });
        return id;
    });

    // Extract Script Blocks (to prevent formatting inside them)
    const scriptBlocks = [];
    html = html.replace(/<script([\s\S]*?)>([\s\S]*?)(?:<\/script>|$)/gi, (match, attributes, content) => {
        const isClosed = /<\/script>\s*$/i.test(match);
        const id = `__SCRIPT_BLOCK_${scriptBlocks.length}__`;
        // Fix escaped newlines inside script blocks
        content = content.replace(/&lt;br\s*\/?(?:&gt;|>)/gi, '\n');
        scriptBlocks.push({ attributes, content, isClosed });
        return id;
    });

    // Extract CSS comments (to prevent formatting inside them)
    const cssComments = [];
    html = html.replace(/\/\*[\s\S]*?\*\//g, (match) => {
        const id = `__CSS_COMMENT_${cssComments.length}__`;
        cssComments.push(match);
        return id;
    });

    // Fix escaped newlines from model (in remaining text)
    html = html.replace(/&lt;br\s*\/?(?:&gt;|>)/gi, '<br>');

    // Janitor image: ![alt](url) -> wrapped img with options button
    const JANITOR_OPTIONS_SVG = `<svg viewBox="0 0 24 24"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>`;
    html = html.replace(/!\[([^\]]*)\]\((https?:\/\/[^)]+)\)/g, (match, alt, src) => {
        return `<span class="janitor-img-wrapper"><img class="janitor-img" src="${src}"${alt ? ` alt="${alt}"` : ''}><button class="janitor-options-btn" type="button" title="Options">${JANITOR_OPTIONS_SVG}</button></span>`;
    });

    // 4. Protect HTML Tags (to prevent <br> injection inside them AND corruption by Quote formatter)
    const tagBlocks = [];
    const blockTagsRegex = /^\s*<\/?(div|p|style|pre|table|ul|ol|li|h[1-6]|blockquote|section|article|header|footer|hr|details|summary|figure|figcaption|svg|path|math|canvas|video|audio|form|fieldset|nav|aside|main)(?:\s+[^>]*?)?>/i;

    // Improved Regex for matching tags with internal quotes/greater-than
    const COMPLETE_TAG_REGEX = /<(?:[^"'>]|"[^"]*"|'[^']*')*?>/g;
    const UNCLOSED_TAG_REGEX = /<(?:[^"'>]|"[^"]*"|'[^']*')*$/;

    // Detect unclosed tag at the very end (streaming)
    let unclosedTag = null;
    const unclosedMatch = html.match(UNCLOSED_TAG_REGEX);
    if (unclosedMatch) {
        unclosedTag = unclosedMatch[0];
        html = html.substring(0, unclosedMatch.index) + "__UNCLOSED_TAG__";
    }

    // Extract all closed tags (including multiline ones)
    html = html.replace(COMPLETE_TAG_REGEX, (match) => {
        const isBlock = blockTagsRegex.test(match);
        const id = `__TAG_BLOCK_${isBlock ? 'BLOCK_' : ''}${tagBlocks.length}__`;
        tagBlocks.push(match);
        return id;
    });

    // 5. Quotes -> Blue
    // Regex matches all block placeholders, Quotes preceded by = (to skip), OR Quotes (to color)
    const quoteRegex = /(__[A-Z_]+_\d+__)|(=[ \t]*"(?:[^"]|\\")*?")|("((?:[^"]|\\")*?)"|"((?:[^"]|\\")*?)"|«((?:[^»])*?)»)/g;
    html = html.replace(quoteRegex, (match, placeholder, skipQuote) => {
        if (placeholder) return placeholder;
        if (skipQuote) return skipQuote;
        return `<span class="chat-quote">${match}</span>`;
    });

    // Unclosed quotes during streaming: opening quote with no closing quote
    // Matches " or « or \u201C at end of text (streaming delta) without a matching closer
    html = html.replace(/([ \t])("(?:[^"\\]|\\.)*?)$/gm, (fullMatch, prefix, unclosed) => {
        return `${prefix}<span class="chat-quote">${unclosed}</span>`;
    });
    html = html.replace(/^(("(?:[^"\\]|\\.)*?))$/gm, (fullMatch, unclosed) => {
        return `<span class="chat-quote">${unclosed}</span>`;
    });
    html = html.replace(/([ \t])(\u201C(?:[^\u201D])*?)$/gm, (fullMatch, prefix, unclosed) => {
        return `${prefix}<span class="chat-quote">${unclosed}</span>`;
    });
    html = html.replace(/^(\u201C(?:[^\u201D])*?)$/gm, (fullMatch, unclosed) => {
        return `<span class="chat-quote">${unclosed}</span>`;
    });
    html = html.replace(/([ \t])(\u00AB(?:[^\u00BB])*?)$/gm, (fullMatch, prefix, unclosed) => {
        return `${prefix}<span class="chat-quote">${unclosed}</span>`;
    });
    html = html.replace(/^(\u00AB(?:[^\u00BB])*?)$/gm, (fullMatch, unclosed) => {
        return `<span class="chat-quote">${unclosed}</span>`;
    });

    // 4. Markdown Parsing (in order of precedence)
    // Horizontal Rule on its own line
    html = html.replace(/^(_{3,}|-{3,}|\*{3,})$/gm, '<hr>');

    // Strikethrough
    html = html.replace(/~~([\s\S]+?)~~/g, '<del>$1</del>');

    // Bold and Italic
    html = html.replace(/\*\*\*([\s\S]+?)\*\*\*/g, '<strong><em>$1</em></strong>');

    // Bold
    html = html.replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>');

    // Italic/Action: *text* -> Gray
    html = html.replace(/\*([\s\S]+?)\*/g, '<em>$1</em>');

    // 5. Color styling for Actions
    // Color all em tags gray for actions
    html = html.replace(/<em>/g, '<em class="chat-italic">');

    // Restore CSS comments
    html = html.replace(/__CSS_COMMENT_(\d+)__/g, (match, index) => {
        return cssComments[index];
    });

    // 6. Paragraphs and Newlines
    // Ensure block-level placeholders are isolated to avoid being wrapped in <p> incorrectly
    html = html.replace(/\n?(__(?:CODE|STYLE|SCRIPT|TAG_BLOCK_BLOCK)_BLOCK_\d+__)\n?/g, '\n\n$1\n\n');

    const paragraphs = html.split(/\n\n+/);
    html = paragraphs
        .map(p => {
            let trimmed = p.trim();
            if (!trimmed) return "";

            // If the chunk is JUST a block-level placeholder, return it as is
            if (/^__(CODE|STYLE|SCRIPT|TAG_BLOCK_BLOCK)_BLOCK_\d+__$/.test(trimmed)) {
                return trimmed;
            }

            // For any chunk that STARTS with a block tag placeholder, do not wrap in <p>
            const startsWithBlock = /^__TAG_BLOCK_BLOCK_\d+__/.test(trimmed);

            // Clean up 'layout' newlines right next to tags before converting remaining ones to <br>
            trimmed = trimmed.replace(/(__TAG_BLOCK_(?:BLOCK_)?\d+__)\s*\n\s*/g, '$1 ');
            trimmed = trimmed.replace(/\s*\n\s*(__TAG_BLOCK_(?:BLOCK_)?\d+__)/g, ' $1');

            const content = trimmed.replace(/\n/g, '<br>');
            return startsWithBlock ? content : `<p>${content}</p>`;
        })
        .filter(p => p !== "")
        .join('');

    // 8. Restore HTML Tags
    html = html.replace(/__TAG_BLOCK_(?:BLOCK_)?(\d+)__/g, (match, index) => {
        return tagBlocks[index];
    });

    // Restore Unclosed Tag (Streaming)
    if (unclosedTag) {
        const escapedUnclosed = unclosedTag
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");
        html = html.replace("__UNCLOSED_TAG__", `<span class="unclosed-tag">${escapedUnclosed}</span>`);
    }

    // Restore Style Blocks
    html = html.replace(/__STYLE_BLOCK_(\d+)__/g, (match, index) => {
        const block = styleBlocks[index];
        if (!block.isClosed) {
            // Render unclosed style as a code block to avoid broken CSS/raw text display
            const escapedContent = block.content.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
            return `<pre class="code-block" data-lang="css"><code>&lt;style${block.attributes}&gt;${escapedContent}</code></pre>`;
        }
        return `<style${block.attributes}>${block.content}</style>`;
    });

    // Restore Script Blocks
    html = html.replace(/__SCRIPT_BLOCK_(\d+)__/g, (match, index) => {
        const block = scriptBlocks[index];
        if (!block.isClosed) {
            const escapedContent = block.content.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
            return `<pre class="code-block" data-lang="javascript"><code>&lt;script${block.attributes}&gt;${escapedContent}</code></pre>`;
        }
        return `<script${block.attributes}>${block.content}</script>`;
    });

    // 7. Restore Code Blocks
    html = html.replace(/__CODE_BLOCK_(\d+)__/g, (match, index) => {
        const block = codeBlocks[index];
        // Escape HTML characters to display code literally
        const escapedCode = block.code
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");

        const content = `<pre class="code-block" data-lang="${block.lang}"><code>${escapedCode}</code></pre>`;
        // If unclosed, we might want to add a cursor or just leave as is
        return content;
    });

    return html;
}

export function formatInputPreview(text) {
    if (!text) return "";

    // Escape HTML
    let html = text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

    // Strikethrough ~~text~~
    html = html.replace(/~~([\s\S]+?)~~/g, '<span class="md-strike">~~$1~~</span>');

    // Use entity to prevent re-matching of asterisks by subsequent regexes
    const AST = '&#42;';

    // Bold+Italic ***text***
    html = html.replace(/\*\*\*([\s\S]+?)\*\*\*/g, `<span class="md-bold-italic">${AST}${AST}${AST}$1${AST}${AST}${AST}</span>`);

    // Bold **text**
    html = html.replace(/\*\*([\s\S]+?)\*\*/g, `<span class="md-bold">${AST}${AST}$1${AST}${AST}</span>`);

    // Italic *text*
    html = html.replace(/\*([\s\S]+?)\*/g, `<span class="md-italic">${AST}$1${AST}</span>`);

    // Convert newlines to <br> for contenteditable (but avoid duplicates)
    // First, normalize any existing <br> tags to newlines temporarily
    html = html.replace(/<br\s*\/?>/gi, '\n');
    // Then convert all newlines to <br> (single conversion)
    html = html.replace(/\n/g, '<br>');

    return html;
}

